def _synchronous_configuration(steps):
    """Drive the same readiness and commit steps for synchronous callers."""
    @wraps(steps)
    def configure(*args, **kwargs):
        with closing(steps(*args, **kwargs)) as pending:
            result = None
            while True:
                try:
                    check = pending.send(result)
                except StopIteration as finished:
                    return finished.value
                result = check()
    return configure


class TokenBucket:
    def __init__(self, capacity: int, fill_rate: float):
        self.capacity = float(capacity)
        self._tokens = float(capacity)
        self.fill_rate = float(fill_rate)
        self.timestamp = time.time()

    async def consume(self, tokens: int = 1):
        while True:
            now = time.time()
            if self._tokens < self.capacity:
                self._tokens += self.fill_rate * (now - self.timestamp)
                if self._tokens > self.capacity:
                    self._tokens = self.capacity
            self.timestamp = now
            if self._tokens >= tokens:
                self._tokens -= tokens
                return True
            await asyncio.sleep(0.1)


class ExitVerdict(tuple):
    """(fired, reason) — plus the NAME of the rule that produced it.

    _peak_giveback_cap_exit hosts two independent rules (the breakeven stop and the
    give-back cap) and its callers used to log a hardcoded "PEAK_GIVEBACK_CAP" for
    whichever one fired. On 2026-08-18 the cap was disabled all day, so all five
    exits logged under that name were breakeven-stop firings — and the log said
    otherwise, which is why the settings block still records that the cap "had never
    fired in any log".

    A tuple subclass rather than a NamedTuple on purpose: every existing caller does
    `fired, reason = ...` (37 tests, plus the backtest probe in
    engine/signal_processor.py), so the verdict has to stay exactly two elements
    long. The rule rides alongside as an attribute instead of a third field.

    No __slots__: CPython rejects a non-empty __slots__ on a tuple subtype, since the
    instance layout is already fixed by the tuple itself.
    """

    def __new__(cls, fired: bool, reason: str = "", rule: str = ""):
        self = super().__new__(cls, (fired, reason))
        self.rule = rule
        return self


class Scanner(ScannerChartMixin, ScannerTelemetryMixin, ScannerRecalculationMixin):
    runtime_source_build = _SCANNER_SOURCE_BUILD
    CORE_CORRELATED_INDICES = {"NIFTY", "BANKNIFTY", "SENSEX"}
    MIDCAP_CORRELATED_INDEX = "MIDCPNIFTY"
    LATE_RECLAIM_BASKET_INDICES = {"NIFTY", "BANKNIFTY", "SENSEX", "MIDCPNIFTY"}

    """Continuous scanning engine — optimized, best-signal selection"""

    @staticmethod
    def _startup_auto_mode(trading_mode: str, configured_auto_mode: Any) -> bool:
        """Allow persisted Auto only for offline replay, never broker-capable startup.

        REAL/PAPER processes must begin manual and earn Auto authority through the
        guarded dashboard command in that same process.  This closes the short race
        between ``scanner.run()`` starting and the premarket worker disarming a stale
        AUTO_MODE value loaded from .env.
        """
        return RuntimeMode.parse(trading_mode) is RuntimeMode.REPLAY and bool(configured_auto_mode)

    def __init__(
        self,
        data_provider: MarketDataProvider,
        candle_builder: CandleBuilder,
        mtf_engine: MultiTimeframeEngine,
        signal_manager: SignalManager,
        intelligence: IntelligenceAggregator,
        trade_manager: TradeManager,
        performance: PerformanceTracker,
        instruments_config: Dict,
        trading_mode: str = "paper",
        on_update: Optional[Callable] = None,
        on_notification: Optional[Callable] = None,
    ):
        requested_runtime_mode = RuntimeMode.parse(trading_mode)
        legacy_trading_mode = requested_runtime_mode.legacy_scanner_mode
        self.data = data_provider
        # Early-entry build-up detector, shadow only (engine/buildup_shadow.py).
        try:
            from engine.buildup_shadow import BuildupShadow
            self._buildup_shadow = BuildupShadow()
            if data_provider is not None:
                data_provider.futures_observer = self._buildup_shadow.observe_futures
        except Exception as exc:
            self._buildup_shadow = None
            logger.debug(f"Build-up shadow unavailable: {exc}")
        self.candles = candle_builder
        self.mtf = mtf_engine
        self.signals = signal_manager
        self.intel = intelligence
        self.intel.derivative_source = getattr(self.data, "get_derivative_participation", None)
        self.session_context = SessionContextAnalyzer()
        self._hourly_regime_detector = RegimeDetector()
        self.rtracker = RegimeTracker.from_settings(get_settings())
        self.trades = trade_manager
        self.trades.scanner = self
        self.trades.mode = legacy_trading_mode
        # The trade manager stamps forensics rows AUTO/MANUAL and cannot see
        # the scanner's flag otherwise.
        self.trades.auto_mode = bool(getattr(self, "auto_mode", False))
        self.trades.ui_logger = self.log_event
        # One broker-boundary authority for every AUTO exposure mutation, including a
        # scale-in or stale-limit replacement on a trade restored after restart. Manual
        # and recovery entries are bypassed by TradeManager before this is evaluated.
        self.trades.entry_submission_guard = self._queued_auto_entry_submission_guard
        # Unlike the Auto/resource guard, the immutable fresh-exposure policy also
        # applies to an operator-approved manual order. Recovery alone bypasses it.
        self.trades.fresh_entry_policy_guard = self._queued_fresh_entry_policy_guard
        self.trades.uts_stop_extension_guard = self._uts_stop_extension_budget_ok
        self.trades.on_trade_closed = self._record_trade_manager_terminal
        self.trades.on_delayed_entry_result = self._record_delayed_entry_result
        # Route Kite's WebSocket order-update feed into the same handler that serves
        # HTTP postbacks (2026-08-16). Both carry the same order payload, and the
        # handler is idempotent and ordering-guarded, so receiving a state on BOTH
        # channels is harmless — the second is dropped as a redelivery. This is the
        # channel that works without a public URL, and kite_postback_url is empty by
        # default, so without it there is no push order-state channel at all.
        try:
            if self.data is not None and hasattr(self.data, "order_update_sink"):
                self.data.order_update_sink = self.trades.on_broker_postback
        except Exception as exc:
            logger.debug(f"Could not attach the Kite order-update sink: {exc}")
        self.perf = performance
        self.config = instruments_config
        self.on_update = on_update
        self.on_notification = on_notification
        # Optional thread-safe poke to push an immediate dashboard trade-panel
        # refresh on entry/exit (wired in main.py to the dashboard updater).
        self.on_trade_event: Optional[Callable] = None

        # â• â•  SUBSCRIPTION MODEL FOR CHARTS â• â•
        # Default to NIFTY 5min to reduce initial payload size
        self.active_chart_instrument = "NIFTY"
        self.active_chart_tf = "5min"
        self.chart_stream_enabled = True
        self._session_breach_lock = threading.RLock()

        self.is_running = False
        self.scan_interval = 1.0
        self.last_scan_time = None
        # Whole-cycle duration INCLUDING the payload build and the websocket
        # broadcast. `latency` measures only up to _update_active_trades, so it
        # cannot see the tail it is most likely to be slow in. Carried from the
        # previous cycle because this cycle's is not known until after the send.
        self._last_cycle_ms = 0
        self.scan_count = 0
        self._analysis_event_generation = 0
        self._last_analysis_signature = None
        self._last_analysis_completed_monotonic = 0.0
        self.runtime_mode = requested_runtime_mode.value
