    @staticmethod
    def _is_non_live_contamination_trade(trade) -> bool:
        """True for ghost / historical / replay rows that must never gate live budgets."""
        if trade is None:
            return True
        if bool(getattr(trade, "is_ghost", False)):
            return True
        tid = str(getattr(trade, "id", "") or "")
        if tid.startswith("H_") or tid.startswith("EOD_"):
            return True
        symbol = str(getattr(trade, "trading_symbol", "") or "").upper()
        if symbol == "FUT_SHADOW" or "FUT SHADOW" in str(getattr(trade, "grade", "") or "").upper():
            return True
        prov = str(getattr(trade, "data_provenance", "") or "").upper()
        if prov in {
            "HISTORICAL",
            "HISTORY",
            "HIST",
            "BACKTEST",
            "REPLAY",
            "SIM",
            "SIMULATION",
            "PAPER_HIST",
        }:
            return True
        return False

    def _trade_counts_for_daily_budget(self, trade) -> bool:
        """Whether a trade row should increment per-index daily entry/loss counters.

        REAL/PAPER live budgets only count broker-backed or genuine live/manual
        entries. Ghost simulation rows (is_ghost=1, often T... ids without
        broker_order_id) never count — they previously contaminated NIFTY to 60+.
        """
        if self._is_non_live_contamination_trade(trade):
            return False
        mode = str(getattr(self, "mode", "") or "").upper()
        if mode == "HISTORICAL":
            # Backtest book intentionally counts non-ghost simulated fills.
            return True
        # LIVE / REAL / MANUAL: require not-sim; prefer broker fill when present.
        broker_id = str(
            getattr(trade, "broker_order_id", None)
            or getattr(trade, "entry_order_id", None)
            or ""
        ).strip()
        if broker_id:
            return True
        prov = str(getattr(trade, "data_provenance", "") or "").upper()
        if prov in {"", "LIVE", "REAL", "MANUAL", "RECOVERY", "PAPER"}:
            return True
        # Unknown non-empty provenance under live modes: do not count.
        return False

    def _purge_session_contamination(
        self,
        *,
        reason: str = "mode_switch",
        force_counter_rebuild: bool = True,
        open_only: bool = False,
    ) -> Dict[str, int]:
        """Drop ghost/historical/replay contamination from in-memory books.

        Used when switching HISTORICAL → REAL/PAPER so same-day simulation T...
        rows cannot block live entry budgets or act as opposite-position guards.
        """
        removed_open = 0
        removed_closed = 0
        open_map = getattr(getattr(self, "trades", None), "open_trades", None)
        if isinstance(open_map, dict):
            for tid, trade in list(open_map.items()):
                if self._is_non_live_contamination_trade(trade):
                    open_map.pop(tid, None)
                    removed_open += 1
        if not open_only:
            closed_list = getattr(getattr(self, "trades", None), "closed_trades", None)
            if isinstance(closed_list, list):
                kept = []
                for trade in closed_list:
                    if self._is_non_live_contamination_trade(trade):
                        removed_closed += 1
                    else:
                        kept.append(trade)
                if removed_closed:
                    self.trades.closed_trades = kept
        if force_counter_rebuild:
            # Force _reset_daily_counters to rebuild from the cleaned book.
            self._last_reset_date = None
            try:
                self._reset_daily_counters()
            except Exception as exc:
                logger.debug(f"Counter rebuild after contamination purge failed: {exc}")
        if removed_open or removed_closed:
            logger.warning(
                f"🧹 Session contamination purge ({reason}): "
                f"removed open={removed_open} closed={removed_closed} ghost/hist/replay rows"
            )
        return {"open": removed_open, "closed": removed_closed}

    @staticmethod
    def _closed_outcome_time(row) -> datetime:
        value = (
            getattr(row, "exit_time", None)
            or getattr(row, "exit_timestamp", None)
            or getattr(row, "timestamp", None)
            or getattr(row, "signal_time", None)
            or getattr(row, "signal_timestamp", None)
            or datetime.min
        )
        if isinstance(value, str):
            try:
                value = datetime.fromisoformat(value.replace("Z", "+00:00"))
            except ValueError:
                return datetime.min
        if not isinstance(value, datetime):
            return datetime.min
        if value.tzinfo is not None:
            value = value.astimezone(IST).replace(tzinfo=None)
        return value

    @staticmethod
    def _closed_outcome_signature(row) -> Tuple[str, ...]:
        instrument = str(getattr(row, "instrument", "") or "").split()[0].upper()
        timeframe = str(getattr(row, "timeframe", "") or "")
        direction = str(getattr(row, "direction", "") or "").upper()
        source_time = (
            getattr(row, "source_signal_timestamp", None)
            or getattr(row, "signal_time", None)
            or getattr(row, "signal_timestamp", None)
            or getattr(row, "entry_time", None)
        )
        if isinstance(source_time, datetime):
            if source_time.tzinfo is not None:
                source_time = source_time.astimezone(IST).replace(tzinfo=None)
            source_time = source_time.isoformat(timespec="seconds")
        symbol = str(getattr(row, "trading_symbol", "") or "").upper()
        lane = str(getattr(row, "source_lane", "") or "").upper()
        return instrument, timeframe, direction, str(source_time or ""), symbol, lane

    @staticmethod
    def _loss_lane_key(instrument: str, timeframe: str = "") -> Tuple[str, str]:
        """(index, timeframe) — the unit a consecutive-loss run belongs to."""
        base = str(instrument or "").split()[0].upper()
        tf = str(timeframe or "").strip().lower() or "unknown"
        return base, tf

    def _refresh_loss_streak_aggregate(self, instrument: str) -> int:
        """This index's streak = its WORST lane, not the sum of its lanes."""
        base = str(instrument or "").split()[0].upper()
        lanes = getattr(self, "_loss_streaks_by_lane", None)
        if not isinstance(lanes, dict):
            self._loss_streaks_by_lane = {}
            lanes = self._loss_streaks_by_lane
        current = max(
            [int(value or 0) for (idx, _tf), value in lanes.items() if idx == base] or [0]
        )
        if not isinstance(getattr(self, "_losses_today", None), dict):
            self._losses_today = {}
        self._losses_today[base] = current
        return current

    def _clear_loss_streak_lanes(self, instrument: str) -> None:
        """Drop every lane for an index once its suspension has been consumed.

        _can_trade_instrument consumes the streak at index level, so the lanes the
        aggregate was computed from must go with it — otherwise the next recorded
        outcome recomputes the aggregate straight back to where it was.
        """
        base = str(instrument or "").split()[0].upper()
        lanes = getattr(self, "_loss_streaks_by_lane", None)
        if isinstance(lanes, dict):
            for lane in [key for key in lanes if key[0] == base]:
                lanes[lane] = 0

    def _record_consecutive_loss_outcome(
        self, instrument: str, pnl: float, timeframe: str = ""
    ) -> int:
        """Track this index's own uninterrupted loss run.

        This used to be measured on the GLOBAL exit tape: any completed trade for another
        index reset this index's run. With four indices trading simultaneously that makes
        the max_consecutive_losses halt structurally unreachable, because the four books
        interleave. Measured on 2026-08-10: NIFTY lost four times and the streak read
        1, 1, 1, 2 — SENSEX and BANKNIFTY exits kept clearing it — so the halt at 3 never
        fired and NIFTY was allowed a fourth losing entry.

        A NIFTY run is now broken only by a NIFTY outcome that is not a loss, which is
        what "3 consecutive NIFTY losses" means to an operator watching one chart. Set
        consecutive_loss_streak_per_index=False to restore the global-tape behaviour.

        Runs are kept per (index, TIMEFRAME) lane and the index's streak is its worst
        lane — restore_point_51's model, ported 2026-08-12. Pooling every timeframe
        into one counter meant two losses on NIFTY 5min and two on NIFTY 15min read
        as a run of four and armed the suspension, though neither chart lost four in
        a row. "A win resets only its own lane. Other indices/timeframes neither
        extend nor erase this lane's streak."
        """
        # split() on an empty string yields [], so [0] raised IndexError and the guard
        # below was unreachable — on the exit-recording path, where a blank instrument
        # would have thrown instead of being ignored.
        parts = str(instrument or "").split()
        instrument = parts[0].upper() if parts else ""
        if not instrument:
            return 0
        streaks = getattr(self, "_losses_today", None)
        if not isinstance(streaks, dict):
            self._losses_today = {}
            streaks = self._losses_today

        if not self._setting_enabled(
            getattr(get_settings(), "consecutive_loss_streak_per_index", True), True
        ):
            previous_instrument = str(
                getattr(self, "_last_loss_outcome_instrument", "") or ""
            ).upper()
            # Lanes are the source of truth the aggregate is recomputed from, so a
            # global-tape reset has to clear them too or the next recorded outcome
            # rebuilds the streak this branch just erased.
            for other in list(streaks):
                if str(other).upper() != instrument:
                    streaks[other] = 0
                    self._clear_loss_streak_lanes(str(other))
            if previous_instrument and previous_instrument != instrument:
                streaks[instrument] = 0
                self._clear_loss_streak_lanes(instrument)

        lanes = getattr(self, "_loss_streaks_by_lane", None)
        if not isinstance(lanes, dict):
            self._loss_streaks_by_lane = {}
            lanes = self._loss_streaks_by_lane
        lane = Scanner._loss_lane_key(instrument, timeframe)
        if float(pnl or 0.0) < 0.0:
            lanes[lane] = int(lanes.get(lane, 0) or 0) + 1
        else:
            lanes[lane] = 0
        self._last_loss_outcome_instrument = instrument
        # Global-tape mode already zeroed the other indices above; recomputing the
        # aggregate from this index's own lanes preserves that.
        return int(self._refresh_loss_streak_aggregate(instrument))

    def _reset_daily_counters(self):
        """Resets daily trading counters at 09:15 AM IST (live-book only)."""
        today = datetime.now(IST).date()
        if getattr(self, "_last_reset_date", None) != today:
            # Live modes: drop open ghosts so they cannot act as active positions.
            mode = str(getattr(self, "mode", "") or "").upper()
            if mode in {"REAL", "PAPER", "MANUAL"}:
                try:
                    self._purge_session_contamination(
                        reason="daily_counter_open_ghost_sweep",
                        force_counter_rebuild=False,
                        open_only=True,
                    )
                except Exception as exc:
                    logger.debug(f"Open ghost sweep skipped: {exc}")
            self._trades_today = {}
            self._losses_today = {}
            self._last_exit_time = {}
            self._last_exit_direction = {}
            self._loss_streaks_by_lane = {}
            self._counted_entry_keys = set()
            self._counted_outcome_signatures = set()
            # _stop_out_reentries was never cleared here, so the "once per index per
            # DAY" allowance its docstring promises was really once per PROCESS
            # LIFETIME: a process kept alive across sessions had stop-out re-entry
            # permanently disabled on any index that used it once.
            self._stop_out_reentries = {}
            self._last_loss_outcome_instrument = ""
            self._last_reset_date = today
            closed_today = []
            # Guard self.trades itself (not just the missing-attribute case): the daily
            # counter reset must never crash the live scan if the trade manager is not
            # yet wired (partial construction / warmup race). Completes the getattr
            # defensiveness the surrounding code already intends.
            _trades_ref = getattr(self, "trades", None)
            for trade in list(getattr(_trades_ref, "closed_trades", []) or []):
                if not self._trade_counts_for_daily_budget(trade):
                    continue
                entry_time = getattr(trade, "entry_time", None)
                if entry_time and entry_time.date() == today:
                    instrument = str(getattr(trade, "instrument", "") or "").split()[0]
                    key = str(getattr(trade, "id", "") or "")
                    if instrument and key:
                        self._counted_entry_keys.add(key)
                        self._trades_today[instrument] = self._trades_today.get(instrument, 0) + 1
                    closed_today.append(trade)
            for trade in list(getattr(_trades_ref, "open_trades", {}).values()):
                if not self._trade_counts_for_daily_budget(trade):
                    continue
                entry_time = getattr(trade, "entry_time", None)
                if entry_time and entry_time.date() == today:
                    instrument = str(getattr(trade, "instrument", "") or "").split()[0]
                    key = str(getattr(trade, "id", "") or "")
                    if instrument and key and key not in self._counted_entry_keys:
                        self._counted_entry_keys.add(key)
                        self._trades_today[instrument] = self._trades_today.get(instrument, 0) + 1
            real_signal_identities = set()
            for trade in list(getattr(_trades_ref, "closed_trades", []) or []) + list(
                getattr(_trades_ref, "open_trades", {}).values()
            ):
                if not self._trade_counts_for_daily_budget(trade):
                    continue
                signal_time = getattr(trade, "signal_time", None)
                if signal_time and signal_time.date() == today:
                    real_signal_identities.add(
                        (
                            str(getattr(trade, "instrument", "") or "").split()[0],
                            str(getattr(trade, "timeframe", "") or ""),
                            signal_time.replace(tzinfo=None).isoformat(),
                        )
                    )

            session_entries = []
            session_exits = []
            for instrument, book in (getattr(self, "_session_trade_candidates", {}) or {}).items():
                for candidate in (book or {}).values():
                    signal_time = getattr(candidate, "signal_timestamp", None)
                    if not signal_time or signal_time.date() != today:
                        continue
                    action = str(getattr(candidate, "action", "ENTRY") or "ENTRY").upper()
                    if action == "ENTRY":
                        if bool(getattr(candidate, "watch_only", False)):
                            continue
                        if not bool(getattr(candidate, "accepted_by_gate", False)):
                            continue
                        identity = (
                            str(instrument or "").split()[0],
                            str(getattr(candidate, "timeframe", "") or ""),
                            signal_time.replace(tzinfo=None).isoformat(),
                        )
                        if identity in real_signal_identities:
                            continue
                        session_entries.append(candidate)
                    elif action == "EXIT":
                        identity = (
                            str(instrument or "").split()[0],
                            str(getattr(candidate, "timeframe", "") or ""),
                            signal_time.replace(tzinfo=None).isoformat(),
                        )
                        if identity not in real_signal_identities:
                            session_exits.append(candidate)

            for candidate in session_entries:
                instrument = str(getattr(candidate, "instrument", "") or "").split()[0]
                key = f"SESSION:{self._candidate_lifecycle_key(candidate)}"
                if instrument and key not in self._counted_entry_keys:
                    self._counted_entry_keys.add(key)
                    self._trades_today[instrument] = self._trades_today.get(instrument, 0) + 1

            # Rebuild one globally chronological exit tape. Processing the real
            # and session books separately made old per-index losses survive
            # intervening trades after a restart.
            all_outcomes = list(closed_today) + list(session_exits)
            all_outcomes.sort(key=self._closed_outcome_time)
            for outcome in all_outcomes:
                signature = self._closed_outcome_signature(outcome)
                if signature in self._counted_outcome_signatures:
                    continue
                self._counted_outcome_signatures.add(signature)
                instrument = str(getattr(outcome, "instrument", "") or "").split()[0]
                self._record_consecutive_loss_outcome(
                    instrument,
                    float(getattr(outcome, "pnl", 0.0) or 0.0),
                    str(getattr(outcome, "timeframe", "") or ""),
                )
                exit_time = self._closed_outcome_time(outcome)
                if exit_time != datetime.min:
                    self._last_exit_time[instrument] = exit_time
                self._note_index_exit_direction(instrument, outcome)
            logger.info("📅 Daily over-trading counters reset.")

    @staticmethod
    def _is_expiring_contract_key(key: Any) -> bool:
        """True for an option contract cache key, false for an index quote key."""
        token = str(key or "").strip().upper()
        if not token:
            return False
        token = token.split("|")[0].split(":")[-1]
        return token.endswith("CE") or token.endswith("PE")

    def _evict_expired_contract_caches(self) -> None:
        """Drop option-contract rows from the provider caches at session rollover."""
        provider = getattr(self, "data", None)
        if provider is None:
            return
        for attr in ("_ws_cache", "_ltp_cache"):
            cache = getattr(provider, attr, None)
            if not isinstance(cache, dict):
                continue
            for key in [key for key in list(cache) if self._is_expiring_contract_key(key)]:
                cache.pop(key, None)
        # History caches are keyed by symbol+window; a new session must refetch rather
        # than serve yesterday's last window.
        for attr in ("_api_hist_cache", "_last_api_hist_fetch"):
            cache = getattr(provider, attr, None)
            if isinstance(cache, dict):
                cache.clear()

    @session_locked
    def _rollover_session_if_needed(self, now_ist: datetime) -> bool:
        """Run session rollover once per date after 09:00, including late startups."""
        if now_ist.time() < dtime(9, 0):
            return False
        session_date = now_ist.date()
        if getattr(self, "_session_rollover_date", None) == session_date:
            return False

        reset_session = getattr(self.trades, "reset_session", None)
        if not callable(reset_session):
            self._session_rollover_date = session_date
            return False
        retained = reset_session(session_date)
        reset_risk = getattr(getattr(self, "risk_manager", None), "reset_for_session", None)
        if callable(reset_risk):
            reset_risk(session_date)
        session_day = session_date.isoformat()
        is_same_session_day = getattr(self, "_session_candidate_day", "") == session_day
        self._session_candidate_day = session_day
        if not is_same_session_day:
            self._session_trade_candidates.clear()
            self._loaded_session_candidate_day = session_day
            self._loaded_session_payload_count = 0
            self._last_empty_session_persist_skip = ""
        self._pending_live_signals.clear()
        self._last_opposite_exit_signal_time.clear()
        self._pending_opposite_exit.clear()
        self._last_intel_fetch.clear()
        self._chain_cache.clear()
        self._chain_quality_cache.clear()
        self._last_chain_fetch.clear()
        self._premium_cache.clear()
        self._candidate_ltp_cache.clear()
        self._candidate_process_cache.clear()
        self._cached_results.clear()
        getattr(self, "_signal_preflight_cache", {}).clear()
        # Yesterday's option contracts never tick again, and their quote/history rows
        # would otherwise sit in the provider caches all day. The 09:00 branch that used
        # to evict them was dead code (`if False and ...`), so nothing cleared them since.
        # Index rows are kept: the pre-open REST lane is filling them at this moment.
        self._evict_expired_contract_caches()
        # Session-anchored context caches: a process running overnight must not
        # serve yesterday's previous close / VIX open into today's gap analysis.
        getattr(self, "_prev_close_cache", {}).clear()
        getattr(self, "_vix_session_open_cache", {}).clear()
        getattr(self, "_breadth_asof_cache", {}).clear()
        # Regime VOTE memory is session-anchored for exactly the same reason.
        # RegimeDetector keeps one label per bar and smooths by majority over the last 5,
        # so a process left running overnight met today's gap-down with four of
        # yesterday's TRENDING_UP bars still in the window: _smooth_regime returned
        # TRENDING_UP and _recent_trend_regime agreed (ups=4>=3). For the first ~20
        # minutes every consumer was wrong at once — regime_aligns admitted BUYs into the
        # gap, uses_tight_trailing left live SHORTs on the loose trend trail, and
        # _regime_opposes_direction withheld LIVE_REVERSAL_EXIT.
        #
        # The only other reset_history() call is guarded by mode == "HISTORICAL", so
        # nothing cleared this in REAL. Safe to clear: _smooth_regime returns None on an
        # empty history and _recent_trend_regime returns None below three entries, so the
        # detector falls back to today's raw label until it has real votes. Indicator
        # warm-up is untouched — ADX/ATR still read the multi-day candle frame; only the
        # vote memory resets.
        try:
            regime_reset = getattr(
                getattr(getattr(self, "intel", None), "regime", None),
                "reset_history",
                None,
            )
            if callable(regime_reset):
                regime_reset()
            getattr(self, "latest_regimes", {}).clear()
            getattr(self, "_timeframe_regimes", {}).clear()
        except Exception as exc:
            # Never let this stop the rollover; broker reconciliation runs below.
            logger.error(f"Session rollover regime reset failed: {exc}")
        try:
            self.market_info = self.expiry.pre_market_check()
        except Exception as exc:
            logger.error(f"Session rollover expiry refresh failed: {exc}")
        try:
            self.trades.reconcile_broker_positions()
        except Exception as exc:
            logger.error(f"Session rollover broker reconciliation failed: {exc}")
        self._session_rollover_date = session_date
        self._daily_reset_done = True
        logger.info(
            f"Session rollover complete for {session_date}; "
            f"active retained={retained['active_retained']}."
        )
        return True

    def _entry_intel_snapshot(self, candidate) -> Dict[str, Any]:
        """Freeze the intel that existed when this entry was accepted.

        The engine computes volume ratios, PCR, cumulative OI, order flow, breadth,
        VWAP position, VIX percentile and the full greeks — and almost none of it
        survived into the trade record. Measured over 239 accepted trades:

            volume.volume_ratio      recorded on   2%
            grading.* pillars        recorded on  33%
            PCR / OI / order_flow    no field existed at all

        Which is why the question "does the intel predict which trades travel?" could
        not be answered from the tracker. The per-minute intelligence_history.json holds
        these series, but it is a rolling 5,000-point window (~10 days) and only 76 of
        240 trades were still joinable to it — the evidence expires before it is used.

        Field paths deliberately mirror intelligence/memory.py's own store() calls, so
        there is ONE definition of where each value lives. Observation only: nothing
        reads this to make a decision, and it must never be able to break an entry.
        """
        snap: Dict[str, Any] = {}
        try:
            instrument = str(getattr(candidate, "instrument", "") or "").split()[0]
            timeframe = str(getattr(candidate, "timeframe", "5min") or "5min")
            intel = self._cached_timeframe_intel(instrument, timeframe, allow_fallback=True) or {}
            if not isinstance(intel, dict):
                return {}

            def dig(*path, default=None):
                cur: Any = intel
                for p in path:
                    if not isinstance(cur, dict):
                        return default
                    cur = cur.get(p)
                return default if cur is None else cur

            def num(value):
                try:
                    f = float(value)
                except (TypeError, ValueError):
                    return None
                return f if f == f and abs(f) != float("inf") else None

            # The regime CONTEXT, not just its label. The exit row records hard_label and
            # adx and drops the rest: atr_pct, bb_width, confidence and kaufman_er are all
            # 0% populated on EXIT rows against 99% on ACCEPTED. So the market can turn
            # mid-trade and nothing in the record shows it — and kaufman_er, the one
            # measure that separates a one-way grind from chop of the same SIZE, is never
            # present on a single traded row (0 of 240). Freezing it here makes both the
            # entry conditions and any change against them visible.
            snap["regime_label"] = str(dig("regime", "regime", default="") or "")
            snap["regime_confidence"] = num(dig("regime", "confidence"))
            snap["kaufman_er"] = num(dig("regime", "kaufman_er"))
            snap["adx"] = num(dig("regime", "adx"))
            snap["atr_pct"] = num(dig("regime", "atr_pct"))
            snap["bb_width"] = num(dig("regime", "bb_width"))
            snap["vol_buy_sell_ratio"] = num(dig("volume", "buy_sell_ratio"))
            snap["volume_ratio"] = num(dig("volume", "volume_ratio"))
            snap["oi_signal"] = str(dig("oi", "signal", default="") or "")
            ca = dig("oi", "cumulative_analysis", default={}) or {}
            if isinstance(ca, dict):
                snap["total_call_oi"] = num(ca.get("total_call_oi"))
                snap["total_put_oi"] = num(ca.get("total_put_oi"))
            pcr = dig("pcr", default={})
            snap["pcr"] = num(pcr.get("pcr", pcr.get("pcr_oi")) if isinstance(pcr, dict) else pcr)
            snap["order_ratio"] = num(dig("order_flow", "ratio"))
            # The OI/PCR pillars as they voted at acceptance, so a later
            # OI_PCR_REVERSAL can prove the book actually turned rather than
            # re-reading the condition the entry was admitted under. Stored only
            # when the chain existed — absent evidence must not read as a benign
            # zero (see _intel_reversal_is_new_evidence).
            entry_direction = str(getattr(candidate, "direction", "") or "").upper()
            if entry_direction in {"LONG", "SHORT"} and Scanner._intel_evidence_is_usable(
                self, intel
            ):
                snap["adverse_votes"] = Scanner._intel_adverse_votes(
                    self, entry_direction, intel
                )
            snap["aggregate_score"] = num(dig("aggregate", "score"))
            snap["breadth_aligned"] = num(dig("breadth_context", "aligned_count"))
            snap["breadth_bias"] = str(dig("breadth_context", "bias", default="") or "")
            snap["day_type"] = str(dig("session_context", "day_type", default="") or "")
            snap["session_confidence"] = num(dig("session_context", "confidence"))
            snap["close_above_vwap_pct"] = num(dig("session_context", "close_above_vwap_pct"))
            greeks = dig("greeks", default={}) or {}
            if isinstance(greeks, dict):
                snap["iv_percentile"] = num(greeks.get("iv_percentile"))
                side = "call" if str(getattr(candidate, "option_type", "")).upper() == "CE" else "put"
                leg = greeks.get(side) or greeks.get("call") or {}
                if isinstance(leg, dict):
                    for g in ("delta", "gamma", "theta", "vega", "iv"):
                        snap[f"{g}"] = num(leg.get(g))
            # VIX is fetched live and percentile-ranked, but reaches the record only as
            # a grading penalty that was non-zero on 3 of 76 rows.
            try:
                cached = (getattr(self, "_premium_cache", {}) or {}).get("INDIAVIX") or {}
                vix = num(cached.get("price"))
                snap["india_vix"] = vix
                if vix is not None:
                    snap["vix_percentile"] = num(self._vix_percentile(vix, datetime.now(IST)))
            except Exception:
                pass
            return {k: v for k, v in snap.items() if v not in (None, "")}
        except Exception as exc:
            # Diagnostics must never interfere with an entry.
            logger.debug(f"Entry intel snapshot skipped: {exc}")
            return {}

    def _record_signal_forensics(self, candidate, trade=None) -> None:
        """Write the ACCEPTED signal to the forensics flight recorder, AUTO or MANUAL.

        Until 2026-09-01 forensics received rows only from TradeManager, i.e. only from
        objects that became TRADES. In Manual mode a signal is announced and never
        becomes one, so an operator running manually had an empty Signal Forensics tab
        with no way to tell that from a broken one -- the whole table held a single row,
        the LFC-TEST-12345 fixture, which the server hides.

        This is the acceptance choke point ("Every acceptance route reaches here"), so
        one row is written per accepted signal in BOTH modes, stamped with which. The
        trade-level transitions written later by TradeManager carry the same stamp, so
        the two never have to be told apart by guesswork.

        HISTORICAL is excluded exactly as the trade writer excludes it: a replay must not
        fill the recorder with rows the operator never traded.
        """
        if str(getattr(self, "mode", "") or "").upper() != "REAL":
            return
        if bool(getattr(self, "is_warmup", False)):
            return
        try:
            now = datetime.now(IST)
            auto = bool(getattr(self, "auto_mode", False))
            contract = getattr(candidate, "contract", None)
            event = {
                "session_date": now.strftime("%Y-%m-%d"),
                "event_ts": now.isoformat(timespec="milliseconds"),
                "lifecycle_id": str(getattr(candidate, "lifecycle_id", "") or ""),
                "signal_id": str(getattr(candidate, "signal_id", "") or ""),
                "instrument": str(getattr(candidate, "instrument", "") or "").split()[0],
                "contract": str(getattr(candidate, "trading_symbol", "") or
                                (contract or "")),
                "symbol_token": str(getattr(candidate, "symbol_token", "") or ""),
                "timeframe": str(getattr(candidate, "timeframe", "") or ""),
                "direction": str(getattr(candidate, "direction", "") or ""),
                "phase": "ACCEPTED",
                # "ACCEPTED" is a value _FORENSIC_DECISIONS already accepts, so the
                # dashboard's decision filter keeps working. AUTO vs MANUAL belongs in
                # execution_mode, its own field, not smuggled into this one.
                "decision": "ACCEPTED",
                "reason_code": "SIGNAL_ACCEPTED",
                "reason_text": (
                    "Accepted and auto-executed" if auto
                    else "Accepted and displayed for manual execution"
                ),
                "source": "scanner",
                "grade": str(getattr(candidate, "grade", "") or ""),
                "confidence": float(getattr(candidate, "confidence", 0.0) or 0.0),
                "engine": str(getattr(candidate, "source_engine", "") or ""),
                "lane": str(getattr(candidate, "source_lane", "") or ""),
                "execution_mode": "AUTO" if auto else "MANUAL",
                "ltp": float(getattr(candidate, "price", 0.0) or 0.0),
                "entry_price": float(getattr(candidate, "entry_price", 0.0)
                                     or getattr(candidate, "price", 0.0) or 0.0),
                "initial_stop": float(getattr(candidate, "stop", 0.0) or 0.0),
                "current_stop": float(getattr(candidate, "stop", 0.0) or 0.0),
                "initial_target": float(getattr(candidate, "target", 0.0) or 0.0),
                "current_target": float(getattr(candidate, "target", 0.0) or 0.0),
                "quote_source": str(getattr(candidate, "entry_quote_source", "") or ""),
                "quote_verified": bool(getattr(candidate, "entry_quote_verified", False)),
                "payload": {
                    "quality": dict(getattr(candidate, "quality_verdict", {}) or {}),
                    "decision_record": dict(getattr(candidate, "decision_record", {}) or {}),
                },
            }
            if not event["lifecycle_id"]:
                return
        except Exception as exc:
            logger.debug(f"Signal forensics event not built: {exc}")
            return

        def _write() -> None:
            try:
                from data.sqlite_db import db
                db.append_signal_lifecycle_events([event])
            except Exception:
                return

        # Off the scan loop, for the same reason the trade-level write is: a slow commit
        # takes db.write_lock and must never cost a scan cycle. Forensics is
        # observability; it may not become an entry failure mode.
        try:
            loop = asyncio.get_running_loop()
            loop.create_task(asyncio.to_thread(_write))
        except RuntimeError:
            threading.Thread(
                target=_write, name="signal-forensics", daemon=True
            ).start()
        except Exception:
            pass

    def _record_accepted_entry(self, candidate: TradeCandidate, trade=None) -> None:
        """Count each accepted live/manual entry exactly once."""
        self._reset_daily_counters()
        # Assign the lifecycle before any ACCEPTED event is written.  The Trade
        # manager creates its own execution id, but rtracker must join the signal
        # admission and the eventual exit to one immutable signal lifecycle.
        lifecycle_id = self._candidate_lifecycle_key(candidate)
        setattr(candidate, "lifecycle_id", lifecycle_id)
        if trade is not None:
            try:
                setattr(trade, "lifecycle_id", lifecycle_id)
            except Exception:
                pass
        # Every acceptance route reaches here, so the snapshot is taken once, at the
        # moment of acceptance, from the intel that actually produced the decision.
        if not getattr(candidate, "entry_intel", None) and self._setting_enabled(
            getattr(get_settings(), "entry_intel_snapshot_enabled", True), True
        ):
            setattr(candidate, "entry_intel", self._entry_intel_snapshot(candidate))
        # Auto mode manages the live Trade, not the candidate, and Trade has no
        # entry_intel field of its own — so without this copy the acceptance
        # evidence never reaches the object the exit guards actually read, and
        # _intel_reversal_is_new_evidence silently falls back to its first-reading
        # latch on every automated trade. Copied, not shared, for the same reason
        # _inherit_exit_entry_metadata copies.
        if trade is not None and not getattr(trade, "entry_intel", None):
            try:
                setattr(trade, "entry_intel", dict(getattr(candidate, "entry_intel", None) or {}))
            except Exception as exc:
                logger.debug(f"Entry intel not carried to trade: {exc}")
        # Snapshot the ENTRY-time quote verification so later feed staleness can
        # never rewrite the acceptance evidence (2026-07-03 session audit).
        if not hasattr(candidate, "entry_quote_verified"):
            setattr(candidate, "entry_quote_verified", bool(getattr(candidate, "quote_verified", False)))
            setattr(candidate, "entry_quote_source", str(getattr(candidate, "quote_source", "") or ""))
        # Before the ACCEPTED row is written: price it where it could have traded.
        try:
            self._rebase_accepted_entry_basis(candidate, trade)
        except Exception as exc:
            logger.debug(f"Accepted entry basis not rebased: {exc}")
        key = str(getattr(trade, "id", "") or self._candidate_history_key(candidate))
        if key in self._counted_entry_keys:
            return
        self._counted_entry_keys.add(key)
        instrument = str(candidate.instrument or "").split()[0]
        self._trades_today[instrument] = self._trades_today.get(instrument, 0) + 1
        # A stop-out retry is spent only when there is an actual non-ghost trade.
        # Manual mode records the displayed signal here before the operator clicks
        # Execute; consuming the allowance at that point would charge an order that
        # was never submitted.  The broker callback commits it below after acceptance.
        self._commit_stop_out_reentry(candidate, trade)
        # Use the same source as the session-ledger pass so rtracker's deterministic
        # id collapses the later duplicate. Recording here starts the shadow horizon at
        # the actual acceptance boundary instead of waiting for a scan-cycle epilogue.
        self._rtracker_record_candidate(
            candidate,
            decision="ACCEPTED",
            source="session_candidate",
        )
        self._record_signal_forensics(candidate, trade)
        self._log_opposing_exposure_telemetry(candidate)
        # Immediately refresh the dashboard signal/trade panel on a fresh entry.
        self._notify_trade_event()

    def _rebase_accepted_entry_basis(self, candidate, trade=None) -> None:
        """Price an accepted advisory row where it could actually have traded.

        2026-09-16: ACCEPTED ``price`` was the contract LTP carried through the 30s
        stabilization window, not the executable quote at acceptance. NIFTY 12:18 was
        accepted at 193.15 against an ask of 190.00 (fill 188.15), and the seven Auto-OFF
        paper rows marked P&L from that carried price: +Rs.1,934.86 against an executable
        estimate of +Rs.1,298.61.

        Basis, first available: the broker-acknowledged Trade's entry price; the policy
        touch stamped moments earlier (ask for bought options and futures longs, bid for
        futures shorts), if it was usable and is still inside the execution quote age; the
        cached contract LTP (non-blocking). The carried value is kept in
        stabilization_start_price and the acceptance quote in acceptance_quote.

        Stop, target and initial stop keep the candidate's geometry around the new basis:
        options scale (same premium fraction and RR), futures shift (same distances).
        Those ratios/distances are all _execution_levels reads from a candidate, so a
        manual Execute of an untrailed row submits the levels it would have without this.
        REAL only -- replay and historical books keep their prices -- and set once.
        """
        if s1_lane_policy.is_utema(candidate):
            return  # Native admission already freezes its mapped premium geometry.
        if str(getattr(self, "mode", "") or "").upper() != "REAL":
            return
        if candidate is None or hasattr(candidate, "stabilization_start_price"):
            return

        def _number(holder, name: str) -> float:
            try:
                value = float(getattr(holder, name, 0.0) or 0.0)
            except (TypeError, ValueError):
                return 0.0
            return value if math.isfinite(value) else 0.0

        old_price = _number(candidate, "price")
        inst_type = str(getattr(candidate, "inst_type", "") or "").upper()
        direction = str(getattr(candidate, "direction", "") or "").upper()
        bid = _number(candidate, "execution_bid_price")
        ask = _number(candidate, "execution_ask_price")
        touch_age = _number(candidate, "execution_touch_age_seconds")
        checked_epoch = _number(candidate, "execution_touch_checked_epoch")
        usable = bool(getattr(candidate, "execution_touch_usable", False))
        try:
            max_age = max(
                0.05,
                float(getattr(get_settings(), "execution_touch_quote_max_age_seconds", 1.5) or 1.5),
            )
        except (TypeError, ValueError):
            max_age = 1.5
        stamp_recent = checked_epoch > 0 and 0.0 <= time.time() - checked_epoch <= max_age
        touch_fresh = bool(
            stamp_recent and usable and bid > 0 and ask >= bid and 0.0 <= touch_age <= max_age
        )
        ltp = _number(candidate, "execution_touch_ltp") if stamp_recent else 0.0

        new_price, source = 0.0, "stabilization_start"
        trade_entry = _number(trade, "entry_price") if trade is not None else 0.0
        if trade_entry > 0:
            new_price, source = trade_entry, "trade_entry_price"
        elif touch_fresh:
            if inst_type == "OPT" or direction == "LONG":
                new_price, source = ask, "execution_touch_ask"
            else:
                new_price, source = bid, "execution_touch_bid"
        if (new_price <= 0 or ltp <= 0) and inst_type in {"OPT", "FUT"}:
            reader = (
                self._get_live_premium_cached
                if inst_type == "OPT"
                else self._get_live_fut_ltp_cached
            )
            try:
                cached_ltp = float(reader(candidate, allow_blocking=False) or 0.0)
            except Exception:
                cached_ltp = 0.0
            if not math.isfinite(cached_ltp):
                cached_ltp = 0.0
            ltp = ltp or cached_ltp
            if new_price <= 0 and cached_ltp > 0:
                new_price, source = cached_ltp, "contract_ltp"

        setattr(candidate, "stabilization_start_price", old_price)
        setattr(candidate, "acceptance_quote", {
            "ltp": ltp,
            "bid": bid,
            "ask": ask,
            "observed_at": str(getattr(candidate, "execution_touch_observed_at", "") or ""),
            "source": str(getattr(candidate, "execution_touch_source", "") or ""),
            "age_seconds": touch_age,
            "usable": usable,
            "executable_price": new_price if new_price > 0 else 0.0,
            "executable_source": source if new_price > 0 else "",
        })
        try:
            rebase_enabled = bool(getattr(get_settings(), "accepted_entry_rebase_enabled", False))
        except Exception:
            rebase_enabled = False
        # Record-only by default: the row keeps its carried price and levels, so the gate
        # inputs paper exits feed are unchanged until entry_spot is re-anchored too.
        if not rebase_enabled or new_price <= 0 or old_price <= 0:
            setattr(candidate, "entry_price_source", "stabilization_start")
            return
        setattr(candidate, "entry_price_source", source)
        if new_price == old_price:
            return

        scale = new_price / old_price
        shift = new_price - old_price

        def _move_levels() -> None:
            for name in ("stop", "target", "initial_stop", "display_stop", "display_target"):
                level = _number(candidate, name) if hasattr(candidate, name) else 0.0
                if level > 0:
                    setattr(candidate, name, level * scale if inst_type == "OPT" else level + shift)

        # A monitor pass between the two writes must never see a stop on the wrong side
        # of the entry, so levels move first when the basis falls and last when it rises.
        if new_price < old_price:
            _move_levels()
            candidate.price = new_price
        else:
            candidate.price = new_price
            _move_levels()

    def _commit_stop_out_reentry(self, candidate, trade=None) -> bool:
        """Commit one retry exactly once at a genuine fresh-exposure boundary."""
        if not bool(getattr(candidate, "stop_out_reentry", False)):
            return False
        if trade is None or bool(getattr(trade, "is_ghost", False)):
            return False
        if bool(getattr(candidate, "stop_out_reentry_committed", False)):
            return False
        instrument = str(getattr(candidate, "instrument", "") or "").split()[0]
        if not instrument:
            return False
        self._note_stop_out_reentry(instrument)
        setattr(candidate, "stop_out_reentry_committed", True)
        try:
            setattr(trade, "stop_out_reentry", True)
        except Exception:
            pass
        return True

    def _record_trade_manager_terminal(self, trade) -> None:
        """Write one authoritative EXIT after final fill/reconciliation accounting."""
        if str(getattr(trade, "status", "") or "").upper() != "CLOSED":
            return
        Scanner._release_uts_repaint_signal(self, trade)
        # The generic tracker hook records a decision-intel snapshot for every
        # lifecycle stage. This callback can run on the broker/reconciliation thread,
        # where recomputing live market intelligence is neither safe nor meaningful;
        # mark the terminal source explicitly instead of touching scanner engines.
        if not getattr(trade, "decision_intel", None):
            setattr(trade, "decision_intel", {"terminal_fill_event": True})
        if hasattr(trade, "runner_stop"):
            setattr(
                trade,
                "runner_stop_at_exit",
                float(getattr(trade, "runner_stop", 0.0) or 0.0),
            )
        # 2026-10-08 audit: a broker fill paired with an acceptance hours earlier (Sep 28
        # NIFTY accepted 09:17, filled 15:12 via MANUAL_SYNC) poisoned fill statistics.
        # Flag such pairings so reports can exclude them; the row itself is kept.
        try:
            signal_at = getattr(trade, "signal_time", None) or getattr(trade, "signal_timestamp", None)
            filled_at = getattr(trade, "entry_time", None)
            filled_epoch = (filled_at.timestamp() if isinstance(filled_at, datetime) and filled_at.tzinfo
                            else IST.localize(filled_at).timestamp() if isinstance(filled_at, datetime)
                            else filled_at)
            if signal_at and isinstance(filled_epoch, (int, float)) and filled_epoch > 0:
                signal_ts = pd.Timestamp(signal_at)
                signal_ts = (signal_ts.tz_convert("Asia/Kolkata") if signal_ts.tzinfo
                             else signal_ts.tz_localize("Asia/Kolkata"))
                gap = abs(float(filled_epoch) - signal_ts.timestamp())
                limit = float(getattr(get_settings(), "fill_pairing_suspect_seconds", 2700.0) or 2700.0)
                intel = getattr(trade, "decision_intel", None)
                if gap > limit and isinstance(intel, dict):
                    intel["pairing_suspect"] = True
                    intel["pairing_gap_seconds"] = round(gap, 1)
        except Exception:
            pass
        self._rtracker_record_candidate(
            trade,
            decision="EXIT",
            reason=str(getattr(trade, "exit_reason", "") or ""),
            source="trade_manager_terminal_fill",
        )
        # Outcome calibration had a store but no producer, so its sample count stayed
        # at zero forever. Record only genuine REAL, fresh-exposure terminal fills and
        # freeze the accepted entry context carried on the Trade. This is evidence
        # collection only; it does not alter any signal or size decision.
        if (
            str(getattr(self, "mode", "") or "").upper() == "REAL"
            and not bool(getattr(trade, "is_ghost", False))
            and not bool(getattr(trade, "is_recovery", False))
            and not bool(getattr(trade, "calibration_outcome_recorded", False))
        ):
            try:
                intel = dict(getattr(trade, "entry_intel", None) or {})
                row = self.outcome_calibration.build_row(trade, intel)
                if self.outcome_calibration.append_rows([row]) == 1:
                    setattr(trade, "calibration_outcome_recorded", True)
                    marker = getattr(getattr(self, "trades", None), "_mark_dirty", None)
                    if callable(marker):
                        marker()
            except Exception as exc:
                logger.warning(f"Outcome calibration write failed for {getattr(trade, 'id', '')}: {exc}")

    def _record_delayed_entry_result(self, trade, accepted: bool) -> None:
        """Rejoin a post-ACK entry rejection to its original signal lifecycle."""
        if accepted:
            return
        lifecycle_id = self._trade_lifecycle_key(trade)
        candidate = self._find_manual_entry_signal_candidate(
            lifecycle_id=lifecycle_id
        )
        loop = getattr(self, "_event_loop", None)
        if candidate is not None and loop is not None and not loop.is_closed():
            try:
                future = asyncio.run_coroutine_threadsafe(
                    self._handle_broker_entry_result(candidate, trade, False),
                    loop,
                )
                future.add_done_callback(
                    lambda result: logger.error(
                        f"Delayed entry-result publish failed for {lifecycle_id}: "
                        f"{result.exception()}"
                    )
                    if result.exception() is not None
                    else None
                )
                return
            except Exception as exc:
                logger.error(f"Could not schedule delayed entry rejection: {exc}")

        # A restart can legitimately leave no in-memory dashboard candidate. Preserve
        # the rejected outcome on the immutable lifecycle instead of silently retaining
        # the earlier ACK as an accepted trade.
        exit_reason = str(getattr(trade, "exit_reason", "") or "").upper()
        if exit_reason == "ENTRY_SUBMISSION_GUARD":
            source = "entry_submission_guard"
        elif exit_reason == "ENTRY_MARGIN_PREFLIGHT":
            source = "entry_margin_preflight"
        elif exit_reason == "SIGNAL_INVALIDATED":
            source = "stale_entry_invalidated"
        else:
            source = "broker_entry_result"
        self._rtracker_record_candidate(
            trade,
            decision="REJECTED",
            reason=str(getattr(trade, "execution_error", "") or exit_reason),
            source=source,
            extra={"delayed_after_ack": True},
        )
        self._notify_trade_event()

    def _log_opposing_exposure_telemetry(self, candidate: TradeCandidate) -> None:
        """Telemetry only: flag simultaneous opposing directions across the
        correlated CORE indices. The 2026-07-03 session held BANKNIFTY long and
        SENSEX short at once — net-flat exposure paying double theta+spread —
        and no guard even noticed."""
        try:
            direction = str(getattr(candidate, "direction", "") or "").upper()
            if direction not in {"LONG", "SHORT"}:
                return
            if self._correlated_index_bucket(getattr(candidate, "instrument", "")) != "CORE":
                return
            opposite = "SHORT" if direction == "LONG" else "LONG"
            opposing = self._correlated_same_direction_exposures(opposite, bucket="CORE")
            if opposing:
                names = sorted({
                    f"{str(getattr(o, 'instrument', '') or '').split()[0]}:{getattr(o, 'timeframe', '') or '?'}"
                    for o in opposing
                })
                logger.warning(
                    f"Opposing correlated exposure: accepting "
                    f"{str(getattr(candidate, 'instrument', '') or '').split()[0]} {direction} while "
                    f"{opposite} exposure is active on {', '.join(names)} (telemetry only)"
                )
        except Exception as exc:
            logger.debug(f"Opposing-exposure telemetry failed: {exc}")

    def _mark_candidate_accepted_time(
        self,
        candidate: TradeCandidate,
        accepted_at: Optional[datetime] = None,
    ) -> None:
        """Separate dashboard entry time from the UT1 source-candle timestamp."""
        if not candidate:
            return
        source_ts = getattr(candidate, "signal_timestamp", None)
        if source_ts is not None and not getattr(candidate, "source_signal_timestamp", None):
            setattr(candidate, "source_signal_timestamp", source_ts)
        if getattr(candidate, "entry_timestamp", None):
            return
        accepted_at = accepted_at or datetime.now(IST)
        if getattr(accepted_at, "tzinfo", None) is not None:
            accepted_at = accepted_at.astimezone(IST).replace(tzinfo=None)
        setattr(candidate, "entry_timestamp", accepted_at)
        if not hasattr(candidate, "display_stop"):
            setattr(candidate, "display_stop", float(getattr(candidate, "stop", 0.0) or 0.0))
        if not hasattr(candidate, "display_target"):
            setattr(candidate, "display_target", float(getattr(candidate, "target", 0.0) or 0.0))

    @staticmethod
    def _mtf_has_forming_signal(mtf_result, now: Optional[datetime] = None) -> bool:
        """Decision-cache results are unsafe while the latest signal candle is forming."""
        if not Scanner._intracandle_signals_enabled():
            return False
        now = now or datetime.now(IST)
        if getattr(now, "tzinfo", None) is not None:
            now = now.astimezone(IST).replace(tzinfo=None)
        # 1min is a live entry lane -- candidate_timeframes inserts it whenever
        # volume-spike and one-minute scalping are on, which is the default. It was
        # the one timeframe this guard did not look at, so a signal on a forming
        # 1-minute candle left the decision cache marked safe and a decision graded
        # on partial data was reused for up to 15 seconds. It is also the lane where
        # that matters most: the fastest chart and the likeliest to repaint.
        for timeframe, attr in (
            ("1min", "results_1min"),
            ("5min", "results_5min"),
            ("15min", "results_15min"),
        ):
            result = getattr(mtf_result, attr, None) or {}
            signals = result.get("signals", []) or []
            if not signals:
                continue
            signal_ts = getattr(signals[-1], "timestamp", None)
            if signal_ts is None:
                continue
            if getattr(signal_ts, "tzinfo", None) is not None:
                signal_ts = signal_ts.astimezone(IST).replace(tzinfo=None)
            # Was `5 if timeframe == "5min" else 15`, a two-way branch that would have
            # given a 1-minute candle a 15-minute forming window.
            minutes = {"1min": 1, "5min": 5, "15min": 15}.get(timeframe, 5)
            if now < signal_ts + timedelta(minutes=minutes):
                return True
        return False

    def _apply_trade_manager_entry_refusal(
        self,
        candidate: TradeCandidate,
        outcome: Optional[Dict[str, Any]] = None,
    ) -> str:
        """Keep a pre-submission refusal out of the filled-trade lifecycle."""
        outcome = outcome if isinstance(outcome, dict) else {}
        code = str(outcome.get("code") or "").upper()
        if code == "ENTRY_MARGIN_PREFLIGHT":
            reason = str(outcome.get("reason") or "insufficient funds for entry")
            candidate.status = "REJECTED - INSUFFICIENT FUNDS"
            setattr(candidate, "exit_reason", "ENTRY_MARGIN_PREFLIGHT")
            source = "entry_margin_preflight"
        else:
            reason = str(
                outcome.get("reason")
                or "TradeManager entry check failed (Risk/Capital/Capacity)"
            )
            candidate.status = "REJECTED - TRADE MANAGER"
            source = "trade_manager_gate"
        setattr(candidate, "accepted_by_gate", False)
        self._rtracker_record_candidate(
            candidate,
            decision="REJECTED",
            reason=reason,
            source=source,
        )
        self._remember_trade_candidates([candidate])
        return reason

    async def _handle_broker_entry_result(
        self,
        candidate: TradeCandidate,
        trade,
        accepted: bool,
    ) -> None:
        """Promote a pending signal only after broker acknowledgement."""
        if accepted:
            try:
                trade_lots = int(getattr(trade, "lots", 0) or 0)
                if trade_lots >= 1 and trade_lots != int(getattr(candidate, "lots", 0) or 0):
                    candidate.lots = trade_lots   # trimmed to the funds available
            except (TypeError, ValueError):
                pass
            if getattr(candidate, "accepted_by_gate", False):
                # Manual signals are recorded when displayed, but the retry allowance
                # belongs to this later execution acknowledgement. Ghost/watch trades
                # are rejected by _commit_stop_out_reentry and consume nothing.
                self._commit_stop_out_reentry(candidate, trade)
                await self._publish_trade_payload_now()
                return
            self._close_superseded_session_entries([candidate])
            self._latest_trade_candidates[candidate.instrument] = [candidate]
            setattr(candidate, "accepted_by_gate", True)
            self._mark_candidate_accepted_time(candidate, getattr(trade, "entry_time", None))
            candidate.status = "TRADE SIGNAL"
            self._record_accepted_entry(candidate, trade)
            self._remember_trade_candidates([candidate])
            
            # Repaint protection belongs only to positions that actually entered
            # from a forming candle. Confirmed candle-close entries are already final.
            if (
                self.mode != "HISTORICAL"
                and not getattr(self, "is_warmup", False)
                and bool(getattr(trade, "entered_intracandle", True))
            ):
                if not uts_lane_policy.is_uts(trade) and not s1_lane_policy.is_utema(trade):
                    asyncio.create_task(self._track_repaint_until_candle_close(trade, candidate))
                elif s1_lane_policy.is_utema(trade):
                    trade.repaint_guard_checked = True
            else:
                setattr(trade, "repaint_guard_checked", True)
            
            self._notify(
                f"{candidate.direction} {candidate.instrument} @ {candidate.price:.2f} "
                f"| Broker acknowledged | TF: {candidate.timeframe}",
                "buy" if candidate.direction == "LONG" else "sell",
            )
        else:
            setattr(candidate, "accepted_by_gate", False)
            guard_blocked = (
                str(getattr(trade, "exit_reason", "") or "").upper()
                == "ENTRY_SUBMISSION_GUARD"
            )
            guard_reason = str(getattr(trade, "execution_error", "") or "").strip()
            if guard_blocked:
                candidate.status = "REJECTED - AUTO SUBMISSION GUARD"
                setattr(candidate, "exit_reason", "ENTRY_SUBMISSION_GUARD")
                rejection_reason = guard_reason or "Automated entry submission guard blocked exposure"
                rejection_source = "entry_submission_guard"
                log_message = (
                    f"Auto submission guard blocked {candidate.instrument} "
                    f"{candidate.direction}: {rejection_reason}. Signal was not counted "
                    "as an accepted trade."
                )
            elif str(getattr(trade, "exit_reason", "") or "").upper() == "ENTRY_MARGIN_PREFLIGHT":
                candidate.status = "REJECTED - INSUFFICIENT FUNDS"
                setattr(candidate, "exit_reason", "ENTRY_MARGIN_PREFLIGHT")
                rejection_reason = guard_reason or "Insufficient funds for broker entry"
                rejection_source = "entry_margin_preflight"
                log_message = (
                    f"Entry margin preflight rejected {candidate.instrument} "
                    f"{candidate.direction}: {rejection_reason}. No order was sent "
                    "and the signal was not counted as an accepted trade."
                )
            elif str(getattr(trade, "exit_reason", "") or "").upper() == "SIGNAL_INVALIDATED":
                candidate.status = "REJECTED - SIGNAL INVALIDATED"
                setattr(candidate, "exit_reason", "SIGNAL_INVALIDATED")
                rejection_reason = guard_reason or "Stale entry invalidated before fill"
                rejection_source = "stale_entry_invalidated"
                log_message = (
                    f"Stale entry invalidated for {candidate.instrument} "
                    f"{candidate.direction}: {rejection_reason}. Signal was not counted "
                    "as an accepted trade."
                )
            else:
                candidate.status = "REJECTED - BROKER"
                rejection_reason = guard_reason or "Broker rejected entry acknowledgement"
                rejection_source = "broker_entry_result"
                log_message = (
                    f"Broker rejected {candidate.instrument} {candidate.direction}; "
                    "signal was not counted as an accepted trade."
                )
            self._rtracker_record_candidate(
                candidate,
                decision="REJECTED",
                reason=rejection_reason,
                source=rejection_source,
            )
            self._forget_signal_display_rows(candidate)
            self.log_event(log_message, "trade")
        await self._publish_trade_payload_now()

    def _iter_manual_entry_signal_candidates(self):
        """Yield accepted manual/session entry rows that may be dashboard-executed."""
        seen = set()
        sources = []
        try:
            sources.extend(
                candidate
                for rows in (getattr(self, "_latest_trade_candidates", {}) or {}).values()
                for candidate in (rows or [])
            )
        except Exception:
            pass
        try:
            store = getattr(self, "_session_trade_candidates", {}) or {}
            sources.extend(
                candidate
                for book in store.values()
                for candidate in (book.values() if isinstance(book, dict) else [])
            )
        except Exception:
            pass
        for candidate in sources:
            if candidate is None:
                continue
            identity = id(candidate)
            if identity in seen:
                continue
            seen.add(identity)
            if str(getattr(candidate, "action", "ENTRY") or "ENTRY").upper() != "ENTRY":
                continue
            if not bool(getattr(candidate, "accepted_by_gate", False)):
                continue
            if bool(getattr(candidate, "watch_only", False)):
                continue
            yield candidate

    def _find_manual_entry_signal_candidate(
        self,
        signal_id: str = "",
        lifecycle_id: str = "",
    ) -> Optional[TradeCandidate]:
        signal_id = str(signal_id or "").strip()
        lifecycle_id = str(lifecycle_id or "").strip()
        for candidate in self._iter_manual_entry_signal_candidates():
            candidate_id = str(
                getattr(candidate, "trade_id", "")
                or getattr(candidate, "id", "")
                or ""
            )
            if not candidate_id:
                try:
                    candidate_id = f"SESSION|{self._candidate_history_key(candidate)}"
                except Exception:
                    candidate_id = ""
            candidate_lifecycle = ""
            try:
                candidate_lifecycle = self._candidate_lifecycle_key(candidate)
            except Exception:
                candidate_lifecycle = str(getattr(candidate, "lifecycle_id", "") or "")
            if signal_id and signal_id == candidate_id:
                return candidate
            if lifecycle_id and lifecycle_id == candidate_lifecycle:
                return candidate
        return None

    @staticmethod
    def _manual_lifecycle_time(value) -> Optional[datetime]:
        if value in (None, ""):
            return None
        if not isinstance(value, datetime):
            try:
                value = datetime.fromisoformat(str(value))
            except Exception:
                return None
        if getattr(value, "tzinfo", None) is not None:
            value = value.astimezone(IST).replace(tzinfo=None)
        return value

    @staticmethod
    def _manual_base_instrument(value) -> str:
        return str(value or "").split()[0].upper()

    def _trade_lifecycle_key(self, trade) -> str:
        explicit = str(getattr(trade, "lifecycle_id", "") or "").strip()
        if explicit:
            return explicit
        signal_time = self._manual_lifecycle_time(
            getattr(trade, "signal_time", None)
            or getattr(trade, "signal_timestamp", None)
            or getattr(trade, "source_signal_timestamp", None)
        )
        if signal_time is None:
            return ""
        return "|".join([
            str(getattr(trade, "instrument", "") or ""),
            str(getattr(trade, "timeframe", "") or ""),
            str(getattr(trade, "direction", "") or ""),
            signal_time.isoformat(),
            str(getattr(trade, "source_lane", "") or ""),
            str(getattr(trade, "trading_symbol", "") or ""),
        ])

    def _open_trade_matches_signal_candidate(
        self,
        trade,
        candidate: TradeCandidate,
        *,
        require_manual_exec: bool = False,
    ) -> bool:
        if not trade or str(getattr(trade, "status", "OPEN") or "").upper() != "OPEN":
            return False
        if require_manual_exec and str(getattr(trade, "exec_type", "") or "").upper() != "M":
            return False
        if self._manual_base_instrument(getattr(trade, "instrument", "")) != self._manual_base_instrument(getattr(candidate, "instrument", "")):
            return False
        if str(getattr(trade, "timeframe", "") or "") != str(getattr(candidate, "timeframe", "") or ""):
            return False
        if str(getattr(trade, "direction", "") or "") != str(getattr(candidate, "direction", "") or ""):
            return False

        trade_symbol = str(getattr(trade, "trading_symbol", "") or "")
        candidate_symbol = str(getattr(candidate, "trading_symbol", "") or "")
        if candidate_symbol and trade_symbol and candidate_symbol != trade_symbol:
            return False

        trade_option = str(getattr(trade, "option_type", "") or "").upper()
        candidate_option = str(getattr(candidate, "option_type", "") or "").upper()
        if trade_option and candidate_option and trade_option != candidate_option:
            return False
        try:
            trade_strike = float(getattr(trade, "atm_strike", 0.0) or 0.0)
            candidate_strike = float(getattr(candidate, "atm_strike", 0.0) or 0.0)
            if trade_strike > 0 and candidate_strike > 0 and abs(trade_strike - candidate_strike) >= 0.01:
                return False
        except Exception:
            pass

        try:
            candidate_lifecycle = self._candidate_lifecycle_key(candidate)
        except Exception:
            candidate_lifecycle = ""
        trade_lifecycle = self._trade_lifecycle_key(trade)
        if candidate_lifecycle and trade_lifecycle and trade_lifecycle != candidate_lifecycle:
            return False
        return True

    def _find_open_trade_for_signal_candidate(
        self,
        candidate: TradeCandidate,
        *,
        require_manual_exec: bool = False,
    ):
        matches = []
        open_trades = getattr(getattr(self, "trades", None), "open_trades", {}) or {}
        trade_rows = open_trades.values() if isinstance(open_trades, dict) else open_trades
        for trade in list(trade_rows or []):
            if self._open_trade_matches_signal_candidate(
                trade,
                candidate,
                require_manual_exec=require_manual_exec,
            ):
                matches.append(trade)
        if not matches:
            return None
        return sorted(
            matches,
            key=lambda trade: getattr(trade, "entry_time", None) or datetime.min,
            reverse=True,
        )[0]

    def _manual_signal_already_open(self, candidate: TradeCandidate) -> bool:
        return self._find_open_trade_for_signal_candidate(candidate) is not None

    def _manual_signal_lifecycle_exited(self, candidate: TradeCandidate) -> bool:
        """Whether a terminal EXIT row already closed this entry's lifecycle.

        A re-signal on the same candle and contract shares the lifecycle key of a signal
        that exited before it (2026-09-15: MIDCPNIFTY 15min REPAINT_ABORT at 11:02, fresh
        signal at 11:08), so an exit only closes an entry accepted at or before it.
        """
        try:
            lifecycle = self._candidate_lifecycle_key(candidate)
        except Exception:
            return False
        entered_at = self._manual_lifecycle_time(getattr(candidate, "entry_timestamp", None))
        rows = []
        try:
            for book in (getattr(self, "_session_trade_candidates", {}) or {}).values():
                rows.extend(book.values() if isinstance(book, dict) else (book or []))
        except Exception:
            pass
        try:
            for latest in (getattr(self, "_latest_trade_candidates", {}) or {}).values():
                rows.extend(latest or [])
        except Exception:
            pass
        for row in rows:
            if row is None or row is candidate:
                continue
            if str(getattr(row, "action", "") or "").upper() != "EXIT":
                continue
            try:
                if self._candidate_lifecycle_key(row) != lifecycle:
                    continue
            except Exception:
                continue
            exited_at = self._manual_lifecycle_time(getattr(row, "exit_timestamp", None))
            if exited_at is None or entered_at is None or exited_at >= entered_at:
                return True
        return False

    def _manual_signal_exit_state(self, candidate: TradeCandidate) -> Dict[str, Any]:
        if bool(getattr(self, "auto_mode", False)) or str(getattr(self, "mode", "") or "").upper() == "HISTORICAL":
            return {}
        trade = self._find_open_trade_for_signal_candidate(candidate, require_manual_exec=True)
        if trade is None:
            return {}
        execution_status = str(getattr(trade, "execution_status", "") or "").upper()
        exit_pending = bool(getattr(trade, "pending_exit", False)) or execution_status in {"EXIT_PENDING", "PARTIAL_EXIT"}
        # Only the open trade's current mark is a quote.  Candidate price/entry are
        # signal-time values and must not be smuggled into the EXIT payload as though
        # they were live market data; zero is now a valid request for a broker MARKET
        # close and lets TradeManager use its explicitly-labelled accounting fallback.
        price = float(getattr(trade, "current_price", 0.0) or 0.0)
        quote_free_market_exit = self._quote_free_broker_exit_available(trade)
        return {
            "manual_entry_executed": True,
            "manual_exit_trade_id": str(getattr(trade, "id", "") or ""),
            "manual_exit_price": price,
            # A market close does not need a quote.  Price is only the local accounting
            # mark until the broker reconciliation supplies the actual fill; disabling
            # the operator's EXIT button because a degraded feed has no mark strands an
            # otherwise closable position for exactly the situation in which a manual
            # escape hatch matters most.
            "manual_exit_quote_available": price > 0,
            "manual_exit_enabled": bool(
                getattr(trade, "id", "")
                and not exit_pending
                and (price > 0 or quote_free_market_exit)
            ),
            "manual_exit_status": (
                "exit_pending"
                if exit_pending
                else ("ready" if price > 0 or quote_free_market_exit else "quote_unavailable")
            ),
            "manual_exit_execution_status": execution_status,
        }

    def _dashboard_close_block_reason(self, trade) -> str:
        if trade is None:
            return "trade_not_found"
        if str(getattr(trade, "status", "") or "").upper() != "OPEN":
            return "trade_not_open"
        execution_status = str(getattr(trade, "execution_status", "") or "").upper()
        if bool(getattr(trade, "pending_exit", False)) or execution_status in {"EXIT_PENDING", "PARTIAL_EXIT"}:
            return "exit_already_pending"
        if execution_status in {"ENTRY_PENDING", "ENTRY_SUBMITTED", "PARTIAL"} and int(getattr(trade, "broker_quantity", 0) or 0) <= 0:
            return "entry_not_confirmed"
        return "trade_manager_rejected"

    def _quote_free_broker_exit_available(self, trade) -> bool:
        """True only when a MARKET order will produce an authoritative broker fill."""
        manager = getattr(self, "trades", None)
        if (
            str(getattr(self, "mode", "") or "").upper() != "REAL"
            or trade is None
            or bool(getattr(trade, "is_ghost", False))
            or not str(getattr(trade, "symbol_token", "") or "").strip()
            or not getattr(manager, "broker", None)
        ):
            return False
        permitted = getattr(manager, "_live_orders_permitted", None)
        try:
            return bool(callable(permitted) and permitted())
        except Exception:
            return False

    async def close_dashboard_trade(
        self,
        trade_id: str,
        price: float = 0.0,
        reason: str = "MANUAL",
    ) -> Dict[str, Any]:
        """Close an open trade from dashboard controls and refresh the panel."""
        tid = str(trade_id or "").strip()
        trade = getattr(getattr(self, "trades", None), "open_trades", {}).get(tid)
        if trade is None:
            return {"status": "blocked", "reason": "trade_not_found", "trade_id": tid}
        quoted_exit_price = float(
            price
            or getattr(trade, "current_price", 0.0)
            or getattr(trade, "exit_price", 0.0)
            or 0.0
        )
        quote_available = quoted_exit_price > 0
        if not quote_available and not self._quote_free_broker_exit_available(trade):
            await self._publish_trade_payload_now()
            return {
                "trade_id": tid,
                "status": "blocked",
                "reason": "quote_unavailable",
            }
        # The manager needs a local mark for interim accounting.  Entry is an explicit
        # fallback only; it is never presented as a current quote or sent to the broker.
        exit_price = quoted_exit_price or float(getattr(trade, "entry_price", 0.0) or 0.0)

        accepted = self.trades.close_trade(tid, exit_price, reason)
        if accepted:
            mark_note = (
                f" @ {exit_price:.2f}"
                if quote_available
                else " @ MARKET (quote unavailable; broker fill will reconcile)"
            )
            self.log_event(f"Manual dashboard EXIT submitted: {tid}{mark_note}", "trade")
            await self._publish_trade_payload_now()
            self._notify_trade_event()
            return {
                "trade_id": tid,
                "status": "submitted",
                "exit_price": exit_price,
                "quote_available": quote_available,
            }
        await self._publish_trade_payload_now()
        return {
            "trade_id": tid,
            "status": "blocked",
            "reason": self._dashboard_close_block_reason(trade),
        }

    def _enforce_strict_instrument_pref_on_candidate(self, candidate: TradeCandidate) -> Tuple[bool, str]:
        """Ensure candidate product matches operator FUT/OPT lock before entry.

        Returns (ok, reason). Under AUTO, no rewrite. Under FUT/OPT, convert in
        place or reject — never silently book the opposite product.
        """
        pref = self._strict_instrument_pref()
        if pref not in {"FUT", "OPT"}:
            return True, "auto"
        current = str(getattr(candidate, "inst_type", "") or "").upper()
        if current in {"CE", "PE"}:
            current = "OPT"
        if pref == "OPT":
            if current == "OPT":
                return True, "already_opt"
            if self._force_candidate_to_options(candidate):
                return True, "converted_to_opt"
            return False, "opt_conversion_failed"
        # FUT-only
        if current == "FUT":
            # Already the right product: fill MISSING contract fields only —
            # never rewrite price/stop/target/lots at this late gate (2026-07-10:
            # the old full re-conversion clobbered tight volume-spike stops and
            # user sizing after the RR engine had already run).
            trading_symbol = str(getattr(candidate, "trading_symbol", "") or "").strip()
            symbol_token = str(getattr(candidate, "symbol_token", "") or "").strip()
            if not trading_symbol or not symbol_token:
                instrument = str(getattr(candidate, "instrument", "") or "").split()[0]
                resolved_symbol, resolved_token = self._resolve_futures_contract_fields(
                    instrument, candidate
                )
                trading_symbol = trading_symbol or resolved_symbol
                symbol_token = symbol_token or resolved_token
                if trading_symbol:
                    candidate.trading_symbol = trading_symbol
                if symbol_token:
                    candidate.symbol_token = symbol_token
            if trading_symbol and symbol_token:
                candidate.inst_type = "FUT"
                candidate.option_type = ""
                return True, "already_fut"
            return False, "fut_contract_unavailable"
        if self._force_candidate_to_futures_1lot(candidate):
            return True, "converted_to_fut"
        return False, "fut_conversion_failed"

    async def execute_manual_signal(
        self,
        signal_id: str = "",
        lifecycle_id: str = "",
    ) -> Dict[str, Any]:
        """Execute an already accepted manual signal from the dashboard table."""
        if self.auto_mode:
            return {"status": "blocked", "reason": "auto_mode_enabled"}
        if str(getattr(self, "mode", "") or "").upper() == "HISTORICAL":
            return {"status": "blocked", "reason": "historical_mode"}
        candidate = self._find_manual_entry_signal_candidate(signal_id, lifecycle_id)
        if candidate is None:
            return {"status": "blocked", "reason": "signal_not_found"}
        if str(getattr(candidate, "status", "") or "").upper() in {"ORDER PENDING", "ENTRY_PENDING", "ENTRY_SUBMITTED"}:
            return {"status": "blocked", "reason": "already_submitted"}
        if self._manual_signal_already_open(candidate):
            return {"status": "blocked", "reason": "already_open"}
        if self._manual_signal_lifecycle_exited(candidate):
            # The session book keeps a cut lifecycle's ENTRY row (still TRADE SIGNAL,
            # accepted_by_gate) beside its EXIT row, and nothing below refuses it: option
            # levels are re-anchored to the live ask, so geometry and final policy see a
            # fresh entry. 2026-09-15 a stale dashboard row offered ENTRY on two signals
            # 17 minutes after EARLY_LOSS_CUT had closed them.
            return {"status": "blocked", "reason": "signal_already_exited"}

        from engine import ut_ema_lane
        if ut_ema_lane.is_lane(candidate):
            return await ut_ema_lane.execute_manual(self, candidate)

        pref_ok, pref_reason = self._enforce_strict_instrument_pref_on_candidate(candidate)
        if not pref_ok:
            candidate.status = f"BLOCKED - {self._strict_instrument_pref()} PREF ({pref_reason})"
            self._remember_trade_candidates([candidate])
            await self._publish_trade_payload_now()
            return {
                "status": "blocked",
                "reason": f"instrument_pref_{pref_reason}",
                "inst_pref": self._strict_instrument_pref(),
            }

        quality_ok, quality_reason, quality_source = self._current_manual_admission_decision(
            candidate,
            lane="MANUAL_DASHBOARD_SUBMIT",
        )
        if not quality_ok:
            candidate.status = "BLOCKED - CURRENT QUALITY POLICY"
            setattr(candidate, "accepted_by_gate", False)
            self._rtracker_record_candidate(
                candidate,
                decision="REJECTED",
                reason=quality_reason,
                source=quality_source,
            )
            self._remember_trade_candidates([candidate])
            await self._publish_trade_payload_now()
            return {"status": "blocked", "reason": quality_reason}

        self._ensure_trade_like_initial_stop(candidate)
        execution_touch_quote = self._candidate_execution_touch_quote(candidate)
        exec_price, exec_stop, exec_target = self._execution_levels(
            candidate,
            execution_touch_quote=execution_touch_quote,
        )
        if exec_price <= 0:
            candidate.status = "QUOTE UNAVAILABLE"
            self._remember_trade_candidates([candidate])
            await self._publish_trade_payload_now()
            return {"status": "blocked", "reason": "quote_unavailable"}

        policy_ok, policy_reason = self._entry_policy_allows(
            candidate,
            execution_levels=(exec_price, exec_stop, exec_target),
            phase="manual_dashboard_submit",
        )
        if not policy_ok:
            candidate.status = "BLOCKED - FINAL ENTRY POLICY"
            self._rtracker_record_candidate(
                candidate,
                decision="REJECTED",
                reason=policy_reason,
                source="manual_final_entry_policy",
            )
            self._remember_trade_candidates([candidate])
            await self._publish_trade_payload_now()
            return {"status": "blocked", "reason": policy_reason}

        exposure = self._option_exposure_decision(candidate, execution_levels=(exec_price, exec_stop, exec_target))
        if not exposure["allowed"]:
            candidate.status = "BLOCKED - SHARED OPTION EXPOSURE"
            self._rtracker_record_candidate(candidate, decision="REJECTED",
                                           reason=exposure["reason"], source="manual_option_exposure")
            return {"status": "blocked", "reason": exposure["reason"]}

        actual_spot = self.candles.get_latest_price(candidate.instrument)
        execution_loop = asyncio.get_running_loop()

        def on_execution_result(executed_trade, accepted, candidate_sig=candidate):
            asyncio.run_coroutine_threadsafe(
                self._handle_broker_entry_result(candidate_sig, executed_trade, accepted),
                execution_loop,
            )

        entry_refusal_outcome: Dict[str, Any] = {}
        trade = self.trades.open_trade(
            instrument=candidate.instrument,
            timeframe=candidate.timeframe,
            direction=candidate.direction,
            price=exec_price,
            trailing_stop=exec_stop,
            lots=candidate.lots,
            lot_size=candidate.lot_size,
            grade=candidate.grade,
            atm_strike=candidate.atm_strike,
            option_type=candidate.option_type,
            target=exec_target,
            rr_ratio=candidate.rr,
            confidence=candidate.confidence,
            instrument_multiplier=candidate.multiplier,
            trading_symbol=candidate.trading_symbol,
            symbol_token=candidate.symbol_token,
            inst_type=candidate.inst_type,
            market_regime=str(getattr(candidate, "market_regime", "") or ""),
            data_provenance=str(getattr(candidate, "data_provenance", "") or ""),
            price_action_verdict=str(getattr(candidate, "price_action_verdict", "") or ""),
            entry_intelligence_score=float(getattr(candidate, "intelligence_score", 0.0) or 0.0),
            strategy_revision=str(getattr(candidate, "strategy_revision", "") or ""),
            strategy_direction_mode=str(getattr(candidate, "strategy_direction_mode", "") or ""),
            exec_type="M",
            entry_spot=float(getattr(candidate, "underlying_entry", 0.0) or actual_spot or 0.0),
            spot_stop=float(getattr(candidate, "underlying_stop", 0.0) or 0.0),
            spot_target=float(getattr(candidate, "underlying_target", 0.0) or 0.0),
            underlying_entry=float(getattr(candidate, "underlying_entry", 0.0) or actual_spot or 0.0),
            underlying_stop=float(getattr(candidate, "underlying_stop", 0.0) or 0.0),
            underlying_target=float(getattr(candidate, "underlying_target", 0.0) or 0.0),
            premium_entry=float(getattr(candidate, "premium_entry", 0.0) or 0.0),
            premium_stop=float(getattr(candidate, "premium_stop", 0.0) or 0.0),
            premium_target=float(getattr(candidate, "premium_target", 0.0) or 0.0),
            geometry_observed_at=str(getattr(candidate, "geometry_observed_at", "") or ""),
            geometry_source=str(getattr(candidate, "geometry_source", "") or ""),
            geometry_verified=bool(getattr(candidate, "geometry_verified", False)),
            expected_move_forecast=dict(getattr(candidate, "expected_move_forecast", {}) or {}),
            entry_policy_verdict=dict(getattr(candidate, "entry_policy_verdict", {}) or {}),
            quality_verdict=dict(getattr(candidate, "quality_verdict", {}) or {}),
            decision_record=dict(getattr(candidate, "decision_record", {}) or {}),
            is_explosive_bypass=bool(getattr(candidate, "is_explosive_bypass", False)),
            is_reversion_scalp=bool(getattr(candidate, "is_reversion_scalp", False)),
            is_recovery=False,
            # The dashboard Execute button is a REAL order. This was is_ghost=True while
            # the UI still reported "ORDER PENDING"/"submitted", so every dashboard
            # execution created a virtual trade and nothing reached the broker — while
            # the toast Execute (make_executor) passed is_ghost=False and was real. Two
            # manual surfaces, opposite behaviour, no visible difference to the operator.
            is_ghost=False,
            entry_time=datetime.now(IST),
            signal_time=getattr(candidate, "signal_timestamp", None),
            signal_fire_mode=getattr(candidate, "signal_fire_mode", "INTRACANDLE"),
            entered_intracandle=bool(getattr(candidate, "entered_intracandle", False)),
            market_wide_reversal_entry=bool(getattr(candidate, "market_wide_reversal_entry", False)),
            volume_spike_entry=bool(getattr(candidate, "volume_spike_entry", False)),
            power_move=bool(getattr(candidate, "power_move", False)),
            source_engine=str(getattr(candidate, "source_engine", "") or ""),
            source_engines=list(getattr(candidate, "source_engines", []) or []),
            source_lane=str(getattr(candidate, "source_lane", "") or ""),
            exit_policy_owner=s1_lane_policy.frozen_exit_owner(candidate),
            quad_union_entry=bool(getattr(candidate, "quad_union_entry", False)),
            raw_union_entry=bool(getattr(candidate, "raw_union_entry", False)),
            initial_stop=exec_stop,
            scalp_lock_mode=bool(getattr(candidate, "scalp_lock_mode", False)),
            execution_touch_quote=execution_touch_quote,
            on_execution_result=on_execution_result,
            lifecycle_id=self._candidate_lifecycle_key(candidate),
            entry_refusal_outcome=entry_refusal_outcome,
        )
        if not trade:
            reason = self._apply_trade_manager_entry_refusal(
                candidate, entry_refusal_outcome
            )
            await self._publish_trade_payload_now()
            return {"status": "blocked", "reason": reason}

        trade.is_live = (self.mode == "REAL")
        Scanner._carry_s1_trade_attrs(trade, candidate)
        candidate.status = "ORDER PENDING"
        self._mark_candidate_accepted_time(candidate, getattr(trade, "entry_time", None))
        self._remember_trade_candidates([candidate])
        self.log_event(
            f"Manual dashboard ENTRY submitted: {candidate.instrument} "
            f"{candidate.direction} {candidate.timeframe} @ {exec_price:.2f}",
            "trade",
        )
        await self._publish_trade_payload_now()
        self._notify_trade_event()
        return {
            "status": "submitted",
            "signal_id": str(
                getattr(candidate, "trade_id", "")
                or getattr(candidate, "id", "")
                or ""
            ),
            "trade_id": str(getattr(trade, "id", "") or ""),
        }

    @staticmethod
    def _intraday_phase_from_session_context(session_ctx: Dict[str, Any]) -> Tuple[str, float]:
        """Map the current context label to a tradable intraday phase.

        The source analyzer still uses labels such as RANGE_DAY/TREND_DAY_* for
        historical compatibility, but the budget rule is phase-based: an hour or
        40-minute range pocket should tighten exactly like a full range phase.
        """
        if not isinstance(session_ctx, dict):
            return "", 0.0
        label = str(
            session_ctx.get("effective_day_type")
            or session_ctx.get("market_phase")
            or session_ctx.get("intraday_phase")
            or session_ctx.get("phase")
            or session_ctx.get("day_type")
            or ""
        ).upper()
        try:
            has_effective_phase = bool(
                session_ctx.get("effective_day_type")
                or session_ctx.get("market_phase")
                or session_ctx.get("intraday_phase")
            )
            raw_confidence = (
                (
                    session_ctx.get("effective_confidence")
                    or session_ctx.get("phase_confidence")
                )
                if has_effective_phase
                else session_ctx.get("confidence")
            )
            confidence = float(raw_confidence or 0.0)
        except Exception:
            confidence = 0.0
        if any(token in label for token in ("RANGE", "CHOP", "SIDEWAY", "MEAN_REVERT")):
            return "RANGE_PHASE", confidence
        if "TREND" in label or "BREAKOUT" in label:
            return "TREND_PHASE", confidence
        return label, confidence

    def _dynamic_trade_budget(self, instrument: str) -> Tuple[int, str]:
        """Accepted-entry budget for an index, scaled by current intraday phase."""
        base = int(getattr(self, "max_trades_per_index", 5) or 5)
        settings = get_settings()
        if not self._setting_enabled(getattr(settings, "dynamic_trade_budget_enabled", True), True):
            return base, "static"
        try:
            intel = self._cached_timeframe_intel(instrument, "5min", allow_fallback=True) or {}
            session_ctx = intel.get("session_context", {}) if isinstance(intel, dict) else {}
            phase, phase_conf = self._intraday_phase_from_session_context(session_ctx)
        except Exception:
            return base, "static"
        min_conf = float(getattr(settings, "dynamic_trade_budget_min_day_confidence", 0.60) or 0.60)
        # Confirmed range/chop phases tighten for every engine. Extra raw arrows
        # in chop increase churn whether the phase lasts all session or 40 minutes.
        if phase_conf >= min_conf and phase == "RANGE_PHASE":
            malus = max(0, int(getattr(settings, "dynamic_trade_budget_range_malus", 2) or 2))
            return max(2, base - malus), f"range-phase malus -{malus}"
        budget = base
        basis = []
        engine = scanner_mode(settings)
        if engine in {"quad_prime", "quad_union"}:
            engine_bonus = max(0, int(getattr(settings, "dynamic_trade_budget_multi_engine_bonus", 4) or 4))
            if engine_bonus:
                budget += engine_bonus
                basis.append(f"multi-engine +{engine_bonus}")
        if phase_conf >= min_conf and phase == "TREND_PHASE":
            bonus = max(0, int(getattr(settings, "dynamic_trade_budget_trend_bonus", 3) or 3))
            if bonus:
                budget += bonus
                basis.append(f"trend-phase +{bonus}")
        budget, vol_note = self._range_scaled_trade_budget(instrument, budget)
        if vol_note:
            basis.append(vol_note)
        return min(20, budget), ", ".join(basis) if basis else "static"

    def _range_scaled_trade_budget(self, instrument: str, budget: int) -> Tuple[int, str]:
        """Shrink the entry budget when the day is offering less to trade.

        Measured across the stored sessions, trades taken per 1% of median daily range:

            W30  0.97% range   15.0 trades/day   15.5 per 1%
            W31  0.62%         8.6               13.8
            W32  0.77%        13.0               16.9
            W33  0.64%        12.0               18.8

        Activity did not fall with opportunity — it rose against it. Holding the trade
        count while the range contracts 34% means the extra trades come from further
        down the quality curve, and the median peak fell Rs.533 -> Rs.78 over the same
        stretch. This ties the budget to the range the day has actually printed so far.

        Uses the session's OWN range to date, not a forecast, and only ever reduces —
        a quiet morning that turns into a trending afternoon widens the measured range
        and the budget recovers with it.
        """
        settings = get_settings()
        base = int(budget or 0)
        if not self._setting_enabled(
            getattr(settings, "range_scaled_budget_enabled", True), True
        ):
            return base, ""
        try:
            reference = float(getattr(settings, "range_scaled_budget_reference_pct", 0.90) or 0.90)
            floor = int(getattr(settings, "range_scaled_budget_min_trades", 3) or 3)
        except (TypeError, ValueError):
            return base, ""
        if reference <= 0:
            return base, ""
        measured = self._session_range_pct(instrument)
        if measured is None or measured <= 0:
            # No measurement is not evidence of a quiet day.
            return base, ""
        scaled = int(round(base * min(1.0, measured / reference)))
        scaled = max(floor, min(base, scaled))
        if scaled >= base:
            return base, ""
        return scaled, f"range {measured:.2f}% of {reference:.2f}% -> {scaled}"

    def _session_range_pct(self, instrument: str) -> Optional[float]:
        """Today's high-low as a percent of the session open, or None if unknowable."""
        try:
            df = self.candles.get_candles(str(instrument or "").split()[0], "5min")
            if df is None or getattr(df, "empty", True) or len(df) < 2:
                return None
            today = datetime.now(IST).date()
            idx = getattr(df, "index", None)
            if idx is None or not hasattr(idx, "date"):
                return None
            day = df[idx.date == today]
            if day.empty:
                return None
            hi = float(day["high"].max()); lo = float(day["low"].min())
            op = float(day["open"].iloc[0])
            if op <= 0 or hi <= lo:
                return None
            return (hi - lo) / op * 100.0
        except Exception as exc:
            logger.debug(f"Session range unavailable for {instrument}: {exc}")
            return None

    def _note_index_exit_direction(self, instrument: str, trade_like) -> None:
        """Remember which way an index was positioned when it last exited.

        The trend-tape cooldown bypass is justified by the FLIP (see
        _index_cooldown_applies), and a flip is a change of direction — which
        cannot be established without knowing the direction that just closed.
        Nothing was recorded, so the bypass could not tell a reversal from the
        same losing bet placed again.
        """
        direction = str(getattr(trade_like, "direction", "") or "").upper()
        if direction not in {"LONG", "SHORT"}:
            return
        base = str(instrument or "").split()[0].upper()
        if not base:
            return
        if not isinstance(getattr(self, "_last_exit_direction", None), dict):
            self._last_exit_direction = {}
        self._last_exit_direction[base] = direction

    def _index_cooldown_applies(self, instrument: str, direction: str = "") -> Tuple[bool, str]:
        """Whether the post-exit cooldown should gate this index right now.

        UT1 is a flip engine — after an opposite-signal exit the reverse entry
        IS the trade, so a blanket cooldown eats reversals. Scoped mode (default)
        applies the cooldown ONLY in chop/range/no-movement pockets where
        post-exit churn is the real risk; trend/normal tape skips it.

        That bypass is about the FLIP, so it is granted only to a genuine one.
        Re-entering the SAME direction that just exited is not the reversal this
        was written for — it is the position that just failed, placed again
        (2026-08-12: NIFTY bought calls at 13:26, was cut at 13:27, bought the
        same calls again at 13:31 and was cut again, all inside a TRENDING_DOWN
        tape; six of that session's nine losing exits were repeats of two
        strikes). A same-direction re-entry that genuinely deserves another go
        still reaches _stop_out_reentry_allowed, which asks whether the trend is
        actually still running instead of inferring it from the regime label.
        """
        settings = get_settings()
        if not self._setting_enabled(
            getattr(settings, "index_cooldown_regime_scoped", True), True
        ):
            return True, "legacy blanket cooldown"
        base = str(instrument or "").split()[0].upper()
        regime = str((getattr(self, "latest_regimes", {}) or {}).get(base, "") or "").upper()
        if any(k in regime for k in ("CHOP", "RANG", "SIDEWAYS", "FLAT")):
            return True, f"choppy regime ({regime})"
        try:
            day_type = self._current_day_type(base)
        except Exception:
            day_type = "UNDECIDED"
        if day_type == "RANGE_DAY":
            return True, "range-day mood"
        last_direction = str(
            (getattr(self, "_last_exit_direction", None) or {}).get(base, "") or ""
        ).upper()
        new_direction = str(direction or "").upper()
        if last_direction and new_direction == last_direction:
            return True, (
                f"same-direction re-entry ({new_direction}) after a {last_direction} exit"
            )
        return False, f"trend/normal tape ({regime or 'UNKNOWN'}/{day_type})"

    def _index_short_span_move_pct(
        self,
        instrument: str,
        *,
        lookback_minutes: Optional[float] = None,
        as_of: Optional[datetime] = None,
        timeframe: str = "1min",
    ) -> float:
        """Absolute short-span index move in percent (e.g. 0.52 for 0.52%).

        Used as the SNAPBACK size-of-event gate: only large, fast moves open the
        reversion window — not micro-chop after every small exit.
        """
        settings = get_settings()
        lb = float(
            lookback_minutes
            if lookback_minutes is not None
            else getattr(settings, "post_exit_reversion_fast_lookback_minutes", 5.0)
            or 5.0
        )
        lb = max(1.0, lb)
        base = str(instrument or "").split()[0].upper()
        if not base:
            return 0.0
        try:
            df = self.candles.get_candles(base, timeframe)
            if df is None or len(df) < 3 or "close" not in getattr(df, "columns", []):
                # Fallback to 5min if 1min thin.
                if timeframe != "5min":
                    return self._index_short_span_move_pct(
                        base,
                        lookback_minutes=lb,
                        as_of=as_of,
                        timeframe="5min",
                    )
                return 0.0
            frame = df
            if as_of is not None:
                frame = Scanner._entry_candles_at(self, frame, timeframe, as_of)
            if frame is None or len(frame) < 2:
                return 0.0
            end_ts = frame.index[-1]
            try:
                start_cut = end_ts - timedelta(minutes=lb)
                prior = frame[frame.index <= start_cut]
                if prior is None or len(prior) == 0:
                    # Not enough history for full lookback: use oldest available bar.
                    start_close = float(frame["close"].iloc[0] or 0.0)
                else:
                    start_close = float(prior["close"].iloc[-1] or 0.0)
            except Exception:
                start_close = float(frame["close"].iloc[0] or 0.0)
            end_close = float(frame["close"].iloc[-1] or 0.0)
            if start_close <= 0 or end_close <= 0:
                return 0.0
            return abs(end_close - start_close) / start_close * 100.0
        except Exception as exc:
            logger.debug(f"Short-span move pct failed for {base}: {exc}")
            return 0.0

    def _index_event_move_qualifies(
        self,
        instrument: str,
        *,
        as_of: Optional[datetime] = None,
        stored: Optional[Dict[str, Any]] = None,
    ) -> Tuple[bool, Dict[str, float]]:
        """SNAPBACK size-of-event: 0.30%+/5m OR 0.40%+/10m (OR logic)."""
        settings = get_settings()
        thr5 = float(getattr(settings, "post_exit_reversion_fast_move_pct", 0.30) or 0.30)
        thr10 = float(getattr(settings, "post_exit_reversion_slow_move_pct", 0.40) or 0.40)
        lb5 = float(getattr(settings, "post_exit_reversion_fast_lookback_minutes", 5.0) or 5.0)
        lb10 = float(getattr(settings, "post_exit_reversion_slow_lookback_minutes", 10.0) or 10.0)
        m5 = 0.0
        m10 = 0.0
        if isinstance(stored, dict):
            try:
                m5 = float(stored.get("move_5m_pct", 0.0) or 0.0)
                m10 = float(stored.get("move_10m_pct", 0.0) or 0.0)
                # Legacy single move_pct: treat as best available.
                legacy = float(stored.get("move_pct", 0.0) or 0.0)
                if m5 <= 0 and m10 <= 0 and legacy > 0:
                    m5 = legacy
                    m10 = legacy
            except Exception:
                pass
        if m5 <= 0:
            m5 = float(self._index_short_span_move_pct(instrument, lookback_minutes=lb5, as_of=as_of) or 0.0)
        if m10 <= 0:
            m10 = float(self._index_short_span_move_pct(instrument, lookback_minutes=lb10, as_of=as_of) or 0.0)
        ok5 = thr5 <= 0 or m5 + 1e-9 >= thr5
        ok10 = thr10 <= 0 or m10 + 1e-9 >= thr10
        # If thresholds positive, need at least one band to pass with its own move.
        qualifies = (thr5 > 0 and m5 + 1e-9 >= thr5) or (thr10 > 0 and m10 + 1e-9 >= thr10)
        if thr5 <= 0 and thr10 <= 0:
            qualifies = True
        band = ""
        if thr5 > 0 and m5 + 1e-9 >= thr5:
            band = f"fast {m5:.2f}%/{lb5:.0f}m"
        elif thr10 > 0 and m10 + 1e-9 >= thr10:
            band = f"slow {m10:.2f}%/{lb10:.0f}m"
        return qualifies, {
            "move_5m_pct": float(m5),
            "move_10m_pct": float(m10),
            "move_pct": float(max(m5, m10)),
            "thr_5m": float(thr5),
            "thr_10m": float(thr10),
            "band": band,
            "ok_5m": bool(ok5 and thr5 > 0 and m5 + 1e-9 >= thr5),
            "ok_10m": bool(ok10 and thr10 > 0 and m10 + 1e-9 >= thr10),
        }

    def _reversion_source_tf_allowed(self, timeframe: str, settings=None) -> bool:
        """SNAPBACK arms only after 5min/15min trades (not continuous 1min scalps)."""
        settings = settings or get_settings()
        allowed = getattr(settings, "post_exit_reversion_source_timeframes", None)
        if not allowed:
            allowed = ["5min", "15min"]
        allow = {str(t or "").lower() for t in list(allowed or [])}
        tf = str(timeframe or "").lower()
        return bool(tf) and tf in allow

    def _arm_reversion_window(
        self,
        instrument: str,
        *,
        direction: str = "",
        reason: str = "",
        when: Optional[datetime] = None,
        source: str = "exit",
        require_big_move: bool = True,
        source_tf: str = "",
    ) -> bool:
        """Open / refresh the post-exit or open-distress reversion window for an index.

        Returns True if the window was armed. When require_big_move is True (default),
        arms only if short-span move qualifies: 0.30%+/5m OR 0.40%+/10m.
        Prefer calling only for 5min/15min source trades (see source_tf filter at
        exit/distress call sites).
        """
        settings = get_settings()
        if not bool(getattr(settings, "post_exit_reversion_enabled", False)):
            return False
        base = str(instrument or "").split()[0].upper()
        if not base:
            return False
        stamp = when or datetime.now(IST).replace(tzinfo=None)
        if getattr(stamp, "tzinfo", None) is not None:
            stamp = stamp.astimezone(IST).replace(tzinfo=None)
        view = str(direction or "").upper()
        if view not in {"LONG", "SHORT"}:
            view = ""
        qualifies, move_info = self._index_event_move_qualifies(base, as_of=stamp)
        if require_big_move and not qualifies:
            logger.info(
                f"🔄 [REVERSION SCALP] Window NOT opened for {base} ({source}): "
                f"5m={move_info.get('move_5m_pct', 0):.2f}% "
                f"(need>={move_info.get('thr_5m', 0.30):.2f}%) / "
                f"10m={move_info.get('move_10m_pct', 0):.2f}% "
                f"(need>={move_info.get('thr_10m', 0.40):.2f}%) "
                f"({reason or 'event'})"
            )
            return False
        if not isinstance(getattr(self, "_last_major_exits", None), dict):
            self._last_major_exits = {}
        self._last_major_exits[base] = {
            "time": stamp,
            "direction": view,
            "reason": str(reason or ""),
            "source": str(source or "exit"),
            "source_tf": str(source_tf or ""),
            "move_pct": float(move_info.get("move_pct", 0.0) or 0.0),
            "move_5m_pct": float(move_info.get("move_5m_pct", 0.0) or 0.0),
            "move_10m_pct": float(move_info.get("move_10m_pct", 0.0) or 0.0),
            "move_band": str(move_info.get("band") or ""),
        }
        self._last_major_exit_time = stamp
        self._last_major_exit_instrument = base
        window_min = float(
            getattr(settings, "post_exit_reversion_window_minutes", 3.0) or 3.0
        )
        band_txt = str(move_info.get("band") or "").strip()
        if not band_txt:
            band_txt = f"move={float(move_info.get('move_pct', 0) or 0):.2f}%"
        logger.info(
            f"🔄 [REVERSION SCALP] {window_min:.0f}-minute window opened for {base} "
            f"({source}) {band_txt} after {view or 'prior'} {reason or 'event'}"
        )
        return True

    def _maybe_arm_reversion_from_exit(
        self,
        instrument: str,
        *,
        exited_like=None,
        reason: str = "",
        pnl: float = 0.0,
        source_tf: str = "",
        when: Optional[datetime] = None,
    ) -> bool:
        """Token-match an exit reason and arm the reversion window when eligible.

        One decision path for BOTH real TradeManager closes and virtual session-
        candidate exits (manual/signal mode). The size-of-event gate inside
        _arm_reversion_window still decides whether a window actually opens.
        Arms after: profitable major wins, stop/loss exits (toggle), OI/PCR /
        intel reverse exits (toggle) — 5min/15min source trades only.
        """
        try:
            settings = get_settings()
            if not bool(getattr(settings, "post_exit_reversion_enabled", False)):
                return False
            base = str(instrument or "").split()[0].upper()
            reason_u = str(reason or "").upper()
            tf = str(source_tf or "").lower()
            if not self._reversion_source_tf_allowed(tf, settings):
                logger.debug(
                    f"🔄 [REVERSION SCALP] skip arm {base}: source TF={tf or '?'} "
                    f"(need 5min/15min trade)"
                )
                return False
            major_win_tokens = (
                "PROFIT_LOCK",
                "SMART_PROFIT_LOCK",
                "PEAK_THREAT",
                "TARGET_HIT",
                "MAJOR_WIN_GUARD",
            )
            stop_loss_tokens = (
                "TRAILING_STOP",
                "STOP_LOSS",
                "HARD_SL",
                "EARLY_LOSS",
                "LOSS_THREAT",
                "RUPEE_LOSS",
                "EOD_LOSS",
            )
            oi_pcr_tokens = (
                "OI_PCR",
                "INTEL_FLIP",
                "PCR_REVERSAL",
                "REGIME_REVERSE",
                "MARKET_WIDE_REVERSAL",
            )
            arm_win = float(pnl or 0.0) > 0 and any(t in reason_u for t in major_win_tokens)
            arm_sl = bool(
                getattr(settings, "post_exit_reversion_include_stop_loss", True)
            ) and any(t in reason_u for t in stop_loss_tokens)
            arm_oi = bool(
                getattr(settings, "post_exit_reversion_include_oi_pcr", True)
            ) and any(t in reason_u for t in oi_pcr_tokens)
            if not (arm_win or arm_sl or arm_oi):
                return False
            try:
                exited_view = self._trade_direction_view(exited_like) if exited_like is not None else ""
            except Exception:
                exited_view = ""
            if exited_view not in {"LONG", "SHORT"}:
                exited_view = str(getattr(exited_like, "direction", "") or "").upper()
            source = "major_win" if arm_win else ("stop_loss" if arm_sl else "oi_pcr")
            return self._arm_reversion_window(
                base,
                direction=exited_view,
                reason=str(reason or ""),
                when=when,
                source=source,
                source_tf=tf,
            )
        except Exception as exc:
            logger.debug(f"Reversion arm-from-exit skipped for {instrument}: {exc}")
            return False

    def _reversion_window_active(self, instrument: str, *, now: Optional[datetime] = None) -> bool:
        """True while the post-exit / open-distress reversion window is open for this index."""
        settings = get_settings()
        if not bool(getattr(settings, "post_exit_reversion_enabled", False)):
            return False
        base = str(instrument or "").split()[0].upper()
        info = (getattr(self, "_last_major_exits", {}) or {}).get(base)
        exit_time = (info or {}).get("time") if isinstance(info, dict) else None
        if exit_time is None and getattr(self, "_last_major_exit_instrument", None) == base:
            exit_time = getattr(self, "_last_major_exit_time", None)
        if exit_time is None:
            return False
        clock = now or datetime.now(IST).replace(tzinfo=None)
        if getattr(clock, "tzinfo", None) is not None:
            clock = clock.astimezone(IST).replace(tzinfo=None)
        if getattr(exit_time, "tzinfo", None) is not None:
            exit_time = exit_time.astimezone(IST).replace(tzinfo=None)
        window_min = float(getattr(settings, "post_exit_reversion_window_minutes", 3.0) or 3.0)
        try:
            elapsed = (clock - exit_time).total_seconds() / 60.0
        except Exception:
            return False
        return 0.0 <= elapsed <= max(0.5, window_min)

    def _maybe_arm_open_distress_reversion(
        self,
        trade,
        *,
        unrealized_pnl: float,
        latest_time: Optional[datetime] = None,
    ) -> bool:
        """Arm reversion window while an open trade is underwater and tape reverses fast.

        Bands (₹, configurable):
          soft:  0 → -soft (default -1000) — reverse must be visible
          deep: -soft → -deep (default -2000) — reverse + fast opposite thrust
        Does not close the trade; only opens the 1min snapback admission window.
        """
        settings = get_settings()
        if not bool(getattr(settings, "post_exit_reversion_enabled", False)):
            return False
        if not bool(getattr(settings, "post_exit_reversion_open_distress_enabled", True)):
            return False
        instrument = str(getattr(trade, "instrument", "") or "").split()[0].upper()
        if not instrument:
            return False
        # SNAPBACK only for structure trades (5min/15min), not 1min scalps.
        trade_tf = str(getattr(trade, "timeframe", "") or "").lower()
        if not self._reversion_source_tf_allowed(trade_tf, settings):
            return False
        # Avoid re-arm spam while window already open.
        if self._reversion_window_active(instrument, now=latest_time):
            return False
        try:
            pnl = float(unrealized_pnl or 0.0)
        except Exception:
            pnl = 0.0
        if pnl >= 0.0:
            return False
        soft = abs(float(getattr(settings, "post_exit_reversion_loss_band_soft_rs", 1000.0) or 1000.0))
        deep = abs(float(getattr(settings, "post_exit_reversion_loss_band_deep_rs", 2000.0) or 2000.0))
        if deep < soft:
            deep = soft
        loss_abs = abs(pnl)
        if loss_abs > deep + 1e-6:
            # Beyond deep band: reversion window is for early/mid distress, not freefall chase.
            return False
        in_soft = loss_abs <= soft + 1e-6
        in_deep = (not in_soft) and loss_abs <= deep + 1e-6
        if not (in_soft or in_deep):
            return False

        try:
            view = self._trade_direction_view(trade)
        except Exception:
            view = str(getattr(trade, "direction", "") or "").upper()
        if view not in {"LONG", "SHORT"}:
            return False
        opposite_sig = "SELL" if view == "LONG" else "BUY"

        reverse_seen = False
        reverse_detail = ""
        # 1) Intel OI/PCR / aggregate flip while underwater
        try:
            intel_result = self._get_trade_intel(trade) if hasattr(self, "_get_trade_intel") else None
            if intel_result:
                rev = self._intel_reversal_reason(view, intel_result, is_losing=True)
                if rev:
                    reverse_seen = True
                    reverse_detail = str(rev)
                else:
                    agg = intel_result.get("aggregate", {}) if isinstance(intel_result, dict) else {}
                    score = float(agg.get("score", 0.0) or 0.0)
                    if view == "LONG" and score < -25.0:
                        reverse_seen = True
                        reverse_detail = f"intel_score={score:.1f}"
                    elif view == "SHORT" and score > 25.0:
                        reverse_seen = True
                        reverse_detail = f"intel_score={score:.1f}"
        except Exception:
            pass

        # 2) Fast opposite thrust on 1min (and optionally 5min)
        fast_opposite = False
        thrust_detail = ""
        try:
            m1 = self._candle_thrust_metrics(instrument, "1min", opposite_sig, as_of=latest_time)
            if m1:
                vol_r = float(m1.get("volume_ratio", 0.0) or 0.0)
                rng_r = float(m1.get("range_atr_ratio", 0.0) or 0.0)
                close_loc = float(m1.get("close_location", 0.0) or 0.0)
                # Soft band: clear opposite candle; deep band: requires stronger burst.
                min_vol = 1.6 if in_soft else 2.2
                min_rng = 1.1 if in_soft else 1.4
                min_close = 0.55 if in_soft else 0.65
                if vol_r >= min_vol and rng_r >= min_rng and close_loc >= min_close:
                    fast_opposite = True
                    thrust_detail = (
                        f"1m thrust vol={vol_r:.1f}x rng={rng_r:.1f}x close={close_loc:.0%}"
                    )
            if not fast_opposite:
                m5 = self._candle_thrust_metrics(instrument, "5min", opposite_sig, as_of=latest_time)
                if m5:
                    vol_r = float(m5.get("volume_ratio", 0.0) or 0.0)
                    rng_r = float(m5.get("range_atr_ratio", 0.0) or 0.0)
                    close_loc = float(m5.get("close_location", 0.0) or 0.0)
                    min_vol = 1.8 if in_soft else 2.4
                    min_rng = 1.2 if in_soft else 1.5
                    min_close = 0.55 if in_soft else 0.65
                    if vol_r >= min_vol and rng_r >= min_rng and close_loc >= min_close:
                        fast_opposite = True
                        thrust_detail = (
                            f"5m thrust vol={vol_r:.1f}x rng={rng_r:.1f}x close={close_loc:.0%}"
                        )
        except Exception:
            pass

        # Soft: reverse OR fast opposite. Deep: both (trend reversed AND moving fast).
        if in_soft:
            if not (reverse_seen or fast_opposite):
                return False
        else:
            if not (reverse_seen and fast_opposite):
                return False

        band_label = "SOFT" if in_soft else "DEEP"
        reason = (
            f"OPEN_DISTRESS_{band_label} pnl=Rs.{pnl:.0f} "
            f"{reverse_detail or 'tape'} {thrust_detail}".strip()
        )
        self._arm_reversion_window(
            instrument,
            direction=view,
            reason=reason,
            when=latest_time,
            source="open_distress",
            source_tf=trade_tf,
        )
        return True

    #: Exit reasons that mean "the stop took us out", i.e. the trade was cut rather
    #: than completed at a target / session end.
    STOP_OUT_EXIT_REASONS = {
        "STOP_HIT",
        "STOP_LOSS",
        "TRAILING_STOP",
        "EARLY_LOSS_CUT",
        "LOSS_THREAT_EXIT",
    }

    def _last_stop_out_exit(self, instrument: str):
        """Most recent closed trade for this index, if it ended on a STOP-type exit.

        Read from the trade book rather than tracked in a parallel dict: the book is
        the single source of truth and survives restarts, so this cannot drift out of
        sync with the four places that record an exit."""
        base = str(instrument or "").split()[0].upper()
        if not base:
            return None
        closed = list(getattr(getattr(self, "trades", None), "closed_trades", []) or [])
        latest = None
        latest_time = None
        for trade in closed:
            if str(getattr(trade, "instrument", "") or "").split()[0].upper() != base:
                continue
            when = getattr(trade, "exit_time", None)
            if when is None:
                continue
            if latest_time is None or when > latest_time:
                latest, latest_time = trade, when
        if latest is None:
            return None
        reason = str(getattr(latest, "exit_reason", "") or "").upper()
        if reason not in self.STOP_OUT_EXIT_REASONS:
            return None
        return latest

    def _stop_out_reentry_allowed(
        self, instrument: str, direction: str, signal_time: datetime,
        adx_value: float = 0.0,
    ) -> Tuple[bool, str]:
        """Allow a second attempt after an early stop-out on a confirmed trend.

        Bypasses ONLY the post-exit cooldown; the daily trade budget and the
        consecutive-loss halt still apply (they are the real risk limits). Requires the
        SAME direction as the stopped trade — this re-takes the idea that was cut, it is
        not a reversal — inside a short window, in an aligned strong-trend regime."""
        settings = get_settings()
        if not self._setting_enabled(getattr(settings, "stop_out_reentry_enabled", False), False):
            return False, "disabled"
        base = str(instrument or "").split()[0].upper()
        last = self._last_stop_out_exit(base)
        if last is None:
            return False, "last exit was not a stop-out"
        want = str(direction or "").upper()
        if want and want != str(getattr(last, "direction", "") or "").upper():
            return False, "opposite direction (reversal, not a re-entry)"

        used = int((getattr(self, "_stop_out_reentries", None) or {}).get(base, 0))
        cap = int(getattr(settings, "stop_out_reentry_max_per_index", 1) or 1)
        if used >= cap:
            return False, f"stop-out re-entry cap {cap} reached"

        exit_time = getattr(last, "exit_time", None)
        if exit_time is None:
            return False, "exit time unknown"
        clock = signal_time or datetime.now(IST)
        try:
            exit_naive = (
                exit_time.astimezone(IST).replace(tzinfo=None)
                if getattr(exit_time, "tzinfo", None) is not None
                else exit_time.replace(tzinfo=None)
            )
            clock_naive = (
                clock.astimezone(IST).replace(tzinfo=None)
                if getattr(clock, "tzinfo", None) is not None
                else clock.replace(tzinfo=None)
            )
            elapsed = (clock_naive - exit_naive).total_seconds() / 60.0
        except Exception:
            return False, "exit time unusable"
        window = float(getattr(settings, "stop_out_reentry_window_minutes", 30.0) or 30.0)
        if elapsed < 0 or elapsed > window:
            return False, f"stop-out {elapsed:.0f}m ago outside {window:.0f}m window"

        regime = str((getattr(self, "latest_regimes", {}) or {}).get(base, "") or "").upper()
        if not is_trending_regime(regime):
            return False, f"regime {regime or 'unknown'} is not a confirmed trend"
        if want == "LONG" and not regime.endswith("_UP"):
            return False, "trend does not agree with re-entry direction"
        if want == "SHORT" and not regime.endswith("_DOWN"):
            return False, "trend does not agree with re-entry direction"

        try:
            adx = float(adx_value or 0.0)
        except Exception:
            adx = 0.0
        floor = float(getattr(settings, "stop_out_reentry_min_adx", 25.0) or 0.0)
        # This is fresh exposure after a realised loss.  "Confirmed strong trend"
        # requires an actual measurement; missing/non-finite evidence may not turn a
        # safety gate into an implicit pass.
        if floor > 0 and (not math.isfinite(adx) or adx <= 0):
            return False, "ADX unavailable for confirmed-trend re-entry"
        if floor > 0 and adx < floor:
            return False, f"ADX {adx:.1f} < {floor:.1f}"
        return True, (
            f"stop-out re-entry: {regime} still aligned {elapsed:.0f}m after "
            f"{str(getattr(last, 'exit_reason', '') or '').upper()}"
        )

    def _note_stop_out_reentry(self, instrument: str) -> None:
        """Count a granted stop-out re-entry so the per-index cap holds for the day."""
        base = str(instrument or "").split()[0].upper()
        if not base:
            return
        if not isinstance(getattr(self, "_stop_out_reentries", None), dict):
            self._stop_out_reentries = {}
        self._stop_out_reentries[base] = int(self._stop_out_reentries.get(base, 0)) + 1

    @staticmethod
    def _restore_saved_lots(target: Dict[str, int], saved) -> None:
        """Apply saved per-index lots (1-50) to the known indices; ignore anything else."""
        if not isinstance(saved, dict):
            return
        for inst, lots in saved.items():
            try:
                n = int(lots)
            except (TypeError, ValueError):
                continue
            key = str(inst).upper()
            if key in target and 1 <= n <= 50:
                target[key] = n

    def _can_trade_instrument(
        self, instrument: str, signal_time: datetime, direction: str = "",
        adx_value: float = 0.0, s1_lane: Any = False,
    ) -> Tuple[bool, str]:
        """Checks if we should allow another trade for this instrument today.

        `direction` is optional and only used by the stop-out re-entry check, which
        requires the SAME direction as the trade that was stopped out.

        Native lanes keep their chart cooldown and hard daily cap. The realized
        option loss suspension applies across owners; synthetic chart P&L cannot
        substitute for that outcome circuit."""
        self._reset_daily_counters()

        # Rule 1: Max accepted entries per index (prevent over-churn). The
        # budget is day-character aware via _dynamic_trade_budget.
        count = self._trades_today.get(instrument, 0)
        if s1_lane:
            budget = int(getattr(self, "max_trades_per_index", 5) or 5)
            if count >= budget:
                return False, f"Max daily trades ({budget}, hard cap) reached"
            losses = self._losses_today.get(instrument, 0)
            if losses >= self.max_consecutive_losses:
                self._losses_today[instrument] = 0
                self._clear_loss_streak_lanes(instrument)
                return False, (
                    f"Same-index loss suspension: skipped one {instrument} candidate "
                    f"after {self.max_consecutive_losses} consecutive losses"
                )
            return True, ""
        budget, budget_basis = self._dynamic_trade_budget(instrument)
        if count >= budget:
            return False, f"Max daily trades ({budget}, {budget_basis}) reached"

        # Rule 2: Max Consecutive Losses — a cooling-off, NOT a lockout.
        #
        # The streak is cleared only by a non-losing outcome on this same index
        # (_record_consecutive_loss_outcome), and a refused index cannot produce
        # one — so refusing every entry at the threshold was self-perpetuating and
        # ran to the closing bell. 2026-08-12: NIFTY and SENSEX each reached four
        # losses between 12:42 and 13:39 on entries the market-wide bypass should
        # never have admitted; at 14:15 the tape reversed and both sat out the
        # largest move of the day, rtracker logging "Index HALTED" against every
        # signal. The streak was evidence about a regime that no longer existed.
        #
        # restore_point_51 skips ONE candidate in the lane and clears the streak
        # (see its _loss_skip_pending_by_lane / consume_loss_skip path). Same
        # semantic here: refuse this signal, reset, let the next one be judged on
        # its own merits. It re-arms on a fresh streak, so a genuinely broken index
        # still pays a skip per run rather than trading straight through.
        losses = self._losses_today.get(instrument, 0)
        if losses >= self.max_consecutive_losses:
            self._losses_today[instrument] = 0
            self._clear_loss_streak_lanes(instrument)
            return False, (
                f"Same-index loss suspension: skipped one {instrument} candidate "
                f"after {self.max_consecutive_losses} consecutive losses"
            )

        # Rule 3: Cooldown Period — regime-scoped (chop/range only by default);
        # flip reversals on trend tape re-enter immediately. The post-major-win
        # reversion window (when enabled) bypasses the cooldown outright.
        cooldown_on, cooldown_basis = self._index_cooldown_applies(instrument, direction)
        if cooldown_on and self._reversion_window_active(instrument):
            cooldown_on = False
            logger.info(
                f"Cooldown bypassed for {instrument}: post-exit reversion window active."
            )
        last_exit = self._last_exit_time.get(instrument)
        if last_exit and self.index_cooldown_minutes > 0 and cooldown_on:
            # Historical replay follows candle time. Live eligibility must use the
            # current evaluation clock: a forming candle's opening timestamp can be
            # earlier than a later exit and otherwise creates impossible negative
            # elapsed time (for example 4 - (-20) => "24m remaining").
            cooldown_clock = (
                signal_time
                if str(getattr(self, "mode", "") or "").upper() == "HISTORICAL"
                else datetime.now(IST).replace(tzinfo=None)
            )
            if getattr(cooldown_clock, "tzinfo", None) is not None:
                cooldown_clock = cooldown_clock.astimezone(IST).replace(tzinfo=None)
            last_exit_naive = (
                last_exit.astimezone(IST).replace(tzinfo=None)
                if getattr(last_exit, "tzinfo", None) is not None
                else last_exit.replace(tzinfo=None)
            )
            diff = max(0.0, (cooldown_clock - last_exit_naive).total_seconds() / 60.0)
            if diff < self.index_cooldown_minutes:
                # Stop-out re-entry: an early stop on a still-running trend gets one
                # more attempt. This bypasses the COOLDOWN only — Rules 1 and 2 above
                # (daily budget, consecutive-loss halt) have already been enforced.
                reentry_ok, reentry_reason = self._stop_out_reentry_allowed(
                    instrument, direction, cooldown_clock, adx_value=adx_value
                )
                if reentry_ok:
                    logger.info(f"Cooldown bypassed for {instrument}: {reentry_reason}.")
                    self.log_event(
                        f"Stop-out re-entry eligible for {instrument}: {reentry_reason}", "trade"
                    )
                    # The caller stamps this on the candidate.  _record_accepted_entry
                    # commits the allowance only after all downstream gates (and, in
                    # REAL auto mode, broker acknowledgement) have succeeded.
                    return True, reentry_reason
                remaining = max(0.0, self.index_cooldown_minutes - diff)
                return False, f"Cooldown active: {remaining:.0f}m remaining ({cooldown_basis})"

        blocked, loss_reason = self._post_loss_cooldown_block(instrument, signal_time)
        if blocked:
            return False, loss_reason

        return True, ""

    def _post_loss_cooldown_block(self, instrument: str, signal_time) -> Tuple[bool, str]:
        """Hold an index out for ut_5min_loss_cooldown_minutes after a LOSING exit.

        SHIPS DISABLED (ut_5min_loss_cooldown_enabled defaults False) so behaviour is
        unchanged until an operator opts in. Until 2026-08-10 the setting was configured
        at 45 and read by nothing but two broadcast payloads — the real post-loss block
        was the flat 3-minute index cooldown, which is additionally regime-scoped, so an
        operator reading the dashboard believed in a protection that did not exist.

        Deliberately NOT bypassed by the stop-out re-entry allowance or the reversion
        window: those exist to re-enter a trend that stopped out early, which is the
        precise behaviour a post-loss cooldown is meant to interrupt. It stacks on top of
        the flat cooldown rather than replacing it.

        "Most recent outcome on this index was a loss" is read off the per-index streak,
        which resets to 0 on any non-loss, so no new state is needed: a non-zero streak
        means _last_exit_time for that index IS the losing exit.
        """
        # split() on an empty string yields [], so [0] would raise rather than fall
        # through to the guard below.
        parts = str(instrument or "").split()
        instrument = parts[0].upper() if parts else ""
        if not instrument:
            return False, ""
        settings = get_settings()
        if not self._setting_enabled(
            getattr(settings, "ut_5min_loss_cooldown_enabled", False), False
        ):
            return False, ""
        try:
            minutes = float(getattr(settings, "ut_5min_loss_cooldown_minutes", 0) or 0)
        except (TypeError, ValueError):
            return False, ""
        if minutes <= 0:
            return False, ""
        streak = int((getattr(self, "_losses_today", None) or {}).get(instrument, 0) or 0)
        if streak < 1:
            return False, ""
        last_exit = (getattr(self, "_last_exit_time", None) or {}).get(instrument)
        if not last_exit:
            return False, ""
        clock = (
            signal_time
            if str(getattr(self, "mode", "") or "").upper() == "HISTORICAL"
            else datetime.now(IST).replace(tzinfo=None)
        )
        if clock is None:
            return False, ""
        if getattr(clock, "tzinfo", None) is not None:
            clock = clock.astimezone(IST).replace(tzinfo=None)
        last_naive = (
            last_exit.astimezone(IST).replace(tzinfo=None)
            if getattr(last_exit, "tzinfo", None) is not None
            else last_exit.replace(tzinfo=None)
        )
        diff = max(0.0, (clock - last_naive).total_seconds() / 60.0)
        if diff >= minutes:
            return False, ""
        return True, (
            f"Post-loss cooldown: {max(0.0, minutes - diff):.0f}m remaining "
            f"after {streak} loss(es) on {instrument}"
        )

